INSERT INTO public.sectors (code, label) VALUES ('transversal', 'Socle transversal');
INSERT INTO public.sectors (code, label) VALUES ('horlogerie', 'Horlogerie');
INSERT INTO public.sectors (code, label) VALUES ('medical', 'Médical');
INSERT INTO public.sectors (code, label) VALUES ('automobile', 'Automobile');
INSERT INTO public.sectors (code, label) VALUES ('aerospatial', 'Aérospatial');
INSERT INTO public.watch_questions (code, label, description) VALUES ('QV0', 'Attribution', 'Le mouvement observé sur un secteur est-il propre à ce secteur, ou porté par la conjoncture générale ?');
INSERT INTO public.watch_questions (code, label, description) VALUES ('QV1', 'Santé structurelle', 'Comment évolue la substance de la branche : production, emploi, tissu d''entreprises ?');
INSERT INTO public.watch_questions (code, label, description) VALUES ('QV2', 'Demande et débouchés', 'Où la demande mondiale croît-elle ou se contracte-t-elle ? Quels flux commerciaux se déplacent ?');
INSERT INTO public.watch_questions (code, label, description) VALUES ('QV3', 'Dynamique géographique', 'Où le centre de gravité du secteur se déplace-t-il : quels pays produisent, importent ou accèdent à une capacité nouvelle ?');
INSERT INTO public.watch_questions (code, label, description) VALUES ('QV4', 'Dynamique technologique', 'Quelle mutation technique recompose la demande de composants : quels procédés, matériaux ou architectures se substituent aux précédents ?');
INSERT INTO public.watch_questions (code, label, description) VALUES ('QV5', 'Impulsions publiques', 'Quelle action publique : dépense, réglementation, condition d''accès : modifie le niveau ou la composition de la demande à moyen terme ?');
INSERT INTO public.sector_watch_questions (sector_code, watch_question_code, formulation, mecanisme, criticite, reponse_gabarit) VALUES ('transversal', 'QV0', 'Le mouvement observé sur un secteur est-il propre à ce secteur, ou porté par la conjoncture générale ?', 'Sans référentiel commun, un recul sectoriel est ininterprétable : une baisse des exportations ne se lit pas de la même manière selon que le commerce mondial recule ou progresse. Le socle transversal fournit le dénominateur de l''attribution.', 'dominante', NULL);
INSERT INTO public.sector_watch_questions (sector_code, watch_question_code, formulation, mecanisme, criticite, reponse_gabarit) VALUES ('horlogerie', 'QV4', 'La montre connectée et les nouveaux matériaux recomposent-ils la demande de composants mécaniques ?', 'Substitution technologique partielle : le produit connecté ne remplace pas le luxe mécanique mais comprime l''entrée de gamme, segment à fort volume de pièces usinées.', 'significative', NULL);
INSERT INTO public.sector_watch_questions (sector_code, watch_question_code, formulation, mecanisme, criticite, reponse_gabarit) VALUES ('horlogerie', 'QV2', 'Vers quels marchés de destination les exportations horlogères se déplacent-elles, et à quel rythme ?', 'Demande finale de luxe, très concentrée géographiquement et sensible aux chocs de change et de droits de douane. Elle se transmet à la sous-traitance avec un décalage de quelques mois.', 'dominante', '{H7.val} {H7.unit} exportés en {H7.per} ({H7.ga} sur un an, en francs, le change neutralisé) ; qui gagne et qui cède du terrain parmi les destinations se lit dans la carte H1.');
INSERT INTO public.sector_watch_questions (sector_code, watch_question_code, formulation, mecanisme, criticite, reponse_gabarit) VALUES ('horlogerie', 'QV3', 'La production horlogère reste-t-elle concentrée en Suisse, ou des pôles concurrents captent-ils des parts du commerce mondial d''articles d''horlogerie ?', 'Concurrence de substitution par le milieu de gamme asiatique. Menace lente mais structurelle sur les volumes de sous-traitance, invisible dans les seules statistiques suisses.', 'significative', 'Les exportations suisses d''articles d''horlogerie (SH 91) varient de {H3.ga} sur un an ; la part suisse du panier mondial se lit dans l''indicateur synthétique (Contexte), les pôles concurrents dans la carte H3.');
INSERT INTO public.sector_watch_questions (sector_code, watch_question_code, formulation, mecanisme, criticite, reponse_gabarit) VALUES ('medical', 'QV3', 'Où se localise la production d''instruments médicaux, et la position suisse s''y érode-t-elle ?', 'Les barrières réglementaires (MDR européen, homologation FDA) freinent les délocalisations : la géographie bouge lentement, ce qui rend tout mouvement observé significatif.', 'significative', 'Les exportations suisses d''instruments médicaux varient de {M1.ga} sur un an ; les pôles et les mouvements de part se lisent dans la carte M1.');
INSERT INTO public.sector_watch_questions (sector_code, watch_question_code, formulation, mecanisme, criticite, reponse_gabarit) VALUES ('automobile', 'QV2', 'Les immatriculations et les flux de pièces indiquent-ils une reprise ou une contraction de la demande adressable ?', 'Les immatriculations mesurent la demande finale, le commerce de pièces mesure le marché directement adressable par la sous-traitance. Les deux peuvent diverger : un marché stable en véhicules peut se contracter en pièces si le contenu mécanique par véhicule diminue.', 'dominante', '{A2.val} immatriculations en Europe en {A2.per} ({A2.vp} depuis le point précédent) ; les ventes électriques mondiales font {A3.ga} sur un an, le flux de pièces du premier déclarant (Allemagne) {A4.ga}.');
INSERT INTO public.sector_watch_questions (sector_code, watch_question_code, formulation, mecanisme, criticite, reponse_gabarit) VALUES ('horlogerie', 'QV5', 'Quelles décisions publiques, droits de douane, accords commerciaux, réglementation Swiss made, modifient les conditions d''accès aux marchés ?', 'L''action publique n''est ici ni acheteuse ni finançante : elle agit sur les conditions d''accès et les règles d''origine, donc sur les prix relatifs et non sur le niveau de la demande. Le choc douanier de 2025 constitue l''exception qui rend la question observable.', 'significative', NULL);
INSERT INTO public.sector_watch_questions (sector_code, watch_question_code, formulation, mecanisme, criticite, reponse_gabarit) VALUES ('medical', 'QV2', 'Quels pays accroissent leurs importations d''instruments médicaux, et leurs dépenses de santé le confirment-elles ?', 'Demande solvabilisée par les systèmes de santé : le budget public précède la commande hospitalière avec un décalage long. Le croisement des deux séries distingue la croissance financée de la croissance annoncée.', 'dominante', 'La demande s''observe en amont : {M7.val} avis de marchés publics UE en {M7.per} ({M7.vp} depuis le mois précédent) et {M8.val} autorisations FDA 510(k) en {M8.per} ({M8.vp}) : deux signaux qui précèdent la production.');
INSERT INTO public.sector_watch_questions (sector_code, watch_question_code, formulation, mecanisme, criticite, reponse_gabarit) VALUES ('aerospatial', 'QV2', 'La demande de transport aérien soutient-elle le renouvellement des flottes ?', 'Le trafic passagers précède les commandes d''appareils de plusieurs trimestres : c''est l''indicateur avancé du cycle civil, en amont du carnet de commandes.', 'significative', '{S7.val} avis de marchés publics aérospatiaux en {S7.per} ({S7.vp} depuis le mois précédent) ; le commerce du premier déclarant (France) varie de {S6.ga} sur un an.');
INSERT INTO public.sector_watch_questions (sector_code, watch_question_code, formulation, mecanisme, criticite, reponse_gabarit) VALUES ('aerospatial', 'QV5', 'Les budgets de défense et les budgets spatiaux publics progressent-ils, et sur quels programmes ?', 'La dépense publique EST la demande : défense et spatial institutionnel sont des marchés budgétaires. Une décision budgétaire n''est pas un signal indirect, c''est une commande à venir.', 'dominante', 'Le premier budget militaire (États-Unis) varie de {S4.ga} sur un an ({S4.per}) ; la demande publique adressée au secteur se compte en avis : {S7.val} en {S7.per}.');
INSERT INTO public.sector_watch_questions (sector_code, watch_question_code, formulation, mecanisme, criticite, reponse_gabarit) VALUES ('automobile', 'QV5', 'Quelles décisions réglementaires, normes d''émission, calendrier d''interdiction du thermique, dispositifs d''incitation, modifient la composition de la demande ?', 'L''action publique ne finance ni n''achète : elle fixe le calendrier de la substitution technologique. Elle agit sur la composition de la demande, non sur son niveau : ce qui explique qu''aucune série statistique budgétaire ne la capte.', 'dominante', '{A10.val} % du signalement automobile du mois porte sur l''action publique (série jeune, à confirmer) ; l''acte réglementaire lui-même est porté par le fait validé ci-dessous.');
INSERT INTO public.sector_watch_questions (sector_code, watch_question_code, formulation, mecanisme, criticite, reponse_gabarit) VALUES ('medical', 'QV4', 'Quelles mutations techniques, chirurgie mini-invasive, robotique, implants personnalisés, recomposent la demande de pièces de précision ?', 'Chaque génération d''instruments modifie les tolérances, les matériaux et les volumes demandés au sous-traitant. L''antériorité du signal se lit dans les dépôts de brevets, plusieurs années avant la commande.', 'dominante', '{M8.val} autorisations FDA 510(k) en {M8.per} ({M8.vp} depuis le mois précédent) : le flux d''entrée des nouveaux dispositifs, l''acte réglementaire qui précède la mise en production.');
INSERT INTO public.sector_watch_questions (sector_code, watch_question_code, formulation, mecanisme, criticite, reponse_gabarit) VALUES ('medical', 'QV5', 'Comment évoluent les dépenses publiques de santé, et quels programmes d''équipement en découlent ?', 'Déterminant médiatisé : la dépense publique solvabilise la demande hospitalière sans être elle-même la commande. Décalage de plusieurs années entre arbitrage budgétaire et appel d''offres.', 'significative', '{M7.val} avis de marchés publics médicaux UE en {M7.per} : la dépense publique de santé au moment précis où elle devient demande adressable.');
INSERT INTO public.sector_watch_questions (sector_code, watch_question_code, formulation, mecanisme, criticite, reponse_gabarit) VALUES ('automobile', 'QV1', 'La production automobile européenne recule-t-elle plus vite que l''industrie manufacturière dans son ensemble ?', 'Cyclicité forte, amplifiée en amont : une variation de production finale se répercute sur les carnets de la sous-traitance avec un effet d''accélérateur. La comparaison à la production manufacturière totale sépare le choc sectoriel du choc conjoncturel.', 'dominante', 'La production automobile UE varie de {A5.ga} sur un an, celle des équipementiers (l''étage que la sous-traitance peut viser) de {A6.ga} : l''écart entre les deux dit si le marché final se découple de la chaîne.');
INSERT INTO public.sector_watch_questions (sector_code, watch_question_code, formulation, mecanisme, criticite, reponse_gabarit) VALUES ('automobile', 'QV4', 'L''électrification recompose-t-elle la demande de composants mécaniques, et à quel rythme selon les marchés ?', 'Substitution technologique à effet asymétrique : disparition des familles de pièces liées à la motorisation thermique, apparition de familles nouvelles, et diminution du nombre total de pièces usinées par véhicule. C''est la mutation la plus déterminante du portefeuille pour un décolleteur.', 'dominante', 'Une voiture neuve sur quatre est électrique : {A11.val} % des ventes mondiales en {A11.per} ({A11.pt} pt sur un an) ; le signalement technologique du mois est à {A9.val} % (série jeune, à confirmer). Le thermique décline pendant que le marché total se maintient ; voir le panneau motorisations.');
INSERT INTO public.sector_watch_questions (sector_code, watch_question_code, formulation, mecanisme, criticite, reponse_gabarit) VALUES ('automobile', 'QV3', 'Le centre de gravité de la production automobile se déplace-t-il hors d''Europe ?', 'La délocalisation de l''assemblage final entraîne celle des chaînes d''approvisionnement de rang 1 et 2. Menace structurelle sur l''avantage de proximité géographique du sous-traitant européen.', 'significative', '{A1.val} véhicules produits dans le monde en {A1.per} ({A1.ga} sur un an) : la carte A1 dit où l''assemblage se déplace, tous véhicules confondus ; le segment électrique ({A3.val} VE vendus, {A3.ga}) dit vers quoi il bascule.');
INSERT INTO public.sector_watch_questions (sector_code, watch_question_code, formulation, mecanisme, criticite, reponse_gabarit) VALUES ('aerospatial', 'QV1', 'Les carnets de commandes et les cadences de livraison des avionneurs assurent-ils une charge pluriannuelle à la chaîne de sous-traitance ?', 'Cycle long : le carnet donne une visibilité de plusieurs années, ce qui inverse la logique de veille. On surveille les révisions de cadence annoncées, non les retournements de demande.', 'dominante', 'La production aéronautique et spatiale UE varie de {S8.ga} sur un an : le constat ; l''annonce se lit dans la demande publique (QV5).');
INSERT INTO public.sector_watch_questions (sector_code, watch_question_code, formulation, mecanisme, criticite, reponse_gabarit) VALUES ('aerospatial', 'QV3', 'Quels États accèdent à une capacité spatiale autonome ?', 'L''entrée de nouveaux acteurs nationaux ouvre des chaînes d''approvisionnement nouvelles, mais souvent captives pour raisons de souveraineté. L''opportunité est réelle et l''accès contraint.', 'significative', '{S3.val} objets lancés dans l''espace en {S3.per} ({S3.ga} sur un an) : la carte dit quels États accèdent à une capacité autonome.');
INSERT INTO public.sector_watch_questions (sector_code, watch_question_code, formulation, mecanisme, criticite, reponse_gabarit) VALUES ('aerospatial', 'QV4', 'Quelles ruptures techniques, lanceurs réutilisables, constellations, propulsion alternative, modifient les volumes et les tolérances demandés ?', 'La réutilisabilité réduit le nombre de lanceurs produits tout en durcissant les exigences de qualification ; les constellations inversent la logique du secteur en demandant de la série là où le spatial était unitaire. Deux effets de sens opposé sur le volume de sous-traitance.', 'dominante', '{S9.val} % du signalement aérospatial du mois porte sur la mutation technique : réutilisable, constellations, fabrication additive. Série d''un point, à confirmer : elle dit le présent du discours, pas encore une tendance.');
INSERT INTO public.sector_watch_questions (sector_code, watch_question_code, formulation, mecanisme, criticite, reponse_gabarit) VALUES ('medical', 'QV1', 'La base productive medtech européenne et suisse croît-elle en volume et en emplois ?', 'Secteur défensif, peu cyclique : la production suit la demande démographique. Tout décrochage est donc un signal structurel et non une fluctuation conjoncturelle.', 'significative', '{M4.val} emplois medtech suisses en {M4.per} ({M4.ga} sur un an) : la base productive nationale, comptée ; la production manufacturière diverse UE, proxy de branche, varie de {M2.ga} sur un an.');
INSERT INTO public.sector_watch_questions (sector_code, watch_question_code, formulation, mecanisme, criticite, reponse_gabarit) VALUES ('horlogerie', 'QV1', 'L''appareil productif horloger suisse se maintient-il en emplois et en établissements, indépendamment du niveau des exportations en valeur ?', 'La branche peut exporter davantage en valeur tout en perdant des établissements : la montée en gamme masque l''érosion du tissu de sous-traitance, qui est précisément le segment concerné par le cas d''illustration.', 'dominante', 'L''appareil productif se compte deux fois : {H2.val} emplois et {H11.val} entreprises dans les industries horlogère et microtechnique suisses en {H2.per} ({H2.ga} et {H11.ga} sur un an) ; le volume de montres mécaniques exportées fait {H9.ga} sur un an, la production horlogère UE {H6.ga}. Si la valeur montait sans les pièces, sans les emplois ni les ateliers, l''érosion serait masquée : les quatre se lisent ici.');
