INSERT INTO public.sources (source_id, name, organisation, url, frequency, format, access, qualification_status, qualified_by, qualified_at, notes) VALUES ('acea', 'Immatriculations de véhicules neufs', 'ACEA', 'https://www.acea.auto', 'mensuelle', 'PDF / communiqués', 'libre', 'certifiee', 'N. Castillo', '2026-08-07 00:00:00+00', 'Communiqués mensuels ; extraction nécessaire');
