INSERT INTO public.sources (source_id, name, organisation, url, frequency, format, access, qualification_status, qualified_by, qualified_at, notes) VALUES ('constructeurs', 'Commandes et livraisons d''avions commerciaux', 'Airbus, Boeing', 'https://www.airbus.com', 'mensuelle', 'Web / Excel', 'libre', 'certifiee', 'N. Castillo', '2026-08-07 00:00:00+00', 'Deux producteurs à consolider');
INSERT INTO public.sources (source_id, name, organisation, url, frequency, format, access, qualification_status, qualified_by, qualified_at, notes) VALUES ('iata', 'Air Passenger Market Analysis', 'IATA', 'https://www.iata.org', 'mensuelle', 'PDF', 'libre', 'a_confirmer', 'N. Castillo', '2026-08-07 00:00:00+00', 'Séries détaillées réservées aux membres');
INSERT INTO public.sources (source_id, name, organisation, url, frequency, format, access, qualification_status, qualified_by, qualified_at, notes) VALUES ('unoosa', 'Objets lancés dans l''espace', 'UNOOSA / Our World in Data', 'https://ourworldindata.org/space-exploration-satellites', 'annuelle', 'CSV', 'libre', 'certifiee', 'N. Castillo', '2026-08-07 00:00:00+00', NULL);
INSERT INTO public.sources (source_id, name, organisation, url, frequency, format, access, qualification_status, qualified_by, qualified_at, notes) VALUES ('ocde', 'Principaux indicateurs économiques et CLI', 'OCDE', 'https://data-explorer.oecd.org', 'mensuelle', 'API + CSV', 'libre', 'certifiee', 'N. Castillo', '2026-08-07 00:00:00+00', 'Vérifié le 10.08.2026 : la série CLI est vivante et mensuelle, mais l''agrégat « OCDE total » n''est plus publié — 22 zones disponibles dont G20, G7, G4E, NAFTA. T1 réancré sur G20. Version du flux non épinglée : la 4.1 ne porte plus la mesure LI. Limitation de débit annoncée par la documentation sans être chiffrée.');
INSERT INTO public.sources (source_id, name, organisation, url, frequency, format, access, qualification_status, qualified_by, qualified_at, notes) VALUES ('fh', 'Statistiques d''exportation horlogère', 'Fédération de l''industrie horlogère suisse', 'https://www.fhs.swiss', 'mensuelle', 'PDF / communiqués', 'libre', 'certifiee', 'N. Castillo', '2026-08-09 00:00:00+00', 'Détail par marché de destination. Provenance précisée le 27.08.2026 : la FH rediffuse la statistique douanière suisse du commerce extérieur (OFDF) en y ajoutant le détail de branche (mécanique/quartz, destinations) — source secondaire d''un chiffre officiel, qualifiée comme référence de branche.');
INSERT INTO public.sources (source_id, name, organisation, url, frequency, format, access, qualification_status, qualified_by, qualified_at, notes) VALUES ('eurostat', 'Eurostat : statistiques conjoncturelles et structurelles', 'Commission européenne', 'https://ec.europa.eu/eurostat/data/database', 'mensuelle', 'API + CSV', 'libre', 'certifiee', 'N. Castillo', '2026-08-07 00:00:00+00', 'API de dissémination sans authentification');
INSERT INTO public.sources (source_id, name, organisation, url, frequency, format, access, qualification_status, qualified_by, qualified_at, notes) VALUES ('comtrade', 'UN Comtrade : commerce international par code SH', 'Nations Unies', 'https://comtradeplus.un.org', 'annuelle', 'API + CSV', 'libre_quota', 'certifiee', 'N. Castillo', '2026-08-07 00:00:00+00', 'Quota sur l''API publique');
INSERT INTO public.sources (source_id, name, organisation, url, frequency, format, access, qualification_status, qualified_by, qualified_at, notes) VALUES ('ofs', 'STATENT : Etablissements et emplois selon année, canton, genre économique et unité d''observation (table px-x-0602010000_103)', 'Office fédéral de la statistique', 'https://www.pxweb.bfs.admin.ch/api/v1/fr/px-x-0602010000_103/px-x-0602010000_103.px', 'annuelle', 'API PX-Web (JSON-stat2, requête POST)', 'libre', 'certifiee', 'N. Castillo', '2026-08-30 00:00:00+00', 'Nomenclature NOGA. Cube STATENT interrogé en POST : le seul URL ne rend pas la donnée, le corps de requête fait partie de la référence (voir source_bindings 142 et 143). H2 = cinq classes NOGA 2652 sommées ; M4 = NOGA 266000 et 3250xx. Unité d''observation 2 (emplois) ; la modalité 1 (établissements) est identifiée, non instrumentée. Consultation à l''écran de la même table : https://www.pxweb.bfs.admin.ch/pxweb/fr/px-x-0602010000_103/px-x-0602010000_103/px-x-0602010000_103.px');
INSERT INTO public.sources (source_id, name, organisation, url, frequency, format, access, qualification_status, qualified_by, qualified_at, notes) VALUES ('esa', 'Budgets spatiaux publics', 'ESA et agences nationales', 'https://www.esa.int', 'annuelle', 'PDF', 'libre', 'a_confirmer', 'N. Castillo', '2026-08-07 00:00:00+00', 'Formats hétérogènes selon les agences');
INSERT INTO public.sources (source_id, name, organisation, url, frequency, format, access, qualification_status, qualified_by, qualified_at, notes) VALUES ('bns', 'Taux de change de référence', 'Banque nationale suisse', 'https://data.snb.ch', 'mensuelle', 'API / CSV', 'libre', 'certifiee', 'N. Castillo', '2026-08-07 00:00:00+00', NULL);
INSERT INTO public.sources (source_id, name, organisation, url, frequency, format, access, qualification_status, qualified_by, qualified_at, notes) VALUES ('fmi', 'World Economic Outlook', 'Fonds monétaire international', 'https://www.imf.org/en/Publications/WEO', 'semestrielle', 'CSV', 'libre', 'certifiee', 'N. Castillo', '2026-08-07 00:00:00+00', NULL);
INSERT INTO public.sources (source_id, name, organisation, url, frequency, format, access, qualification_status, qualified_by, qualified_at, notes) VALUES ('kof', 'Baromètre conjoncturel KOF', 'KOF ETH Zurich', 'https://data.kof.ethz.ch', 'mensuelle', 'API / CSV', 'libre', 'certifiee', 'N. Castillo', '2026-08-17 00:00:00+00', 'API v2 publique sans clé (access_type=public), CSV date/valeur, mensuel depuis 1991. Vérifiée en réponse réelle le 17.08.2026. Ancienne API v1 hors service — motif du re-sourçage documenté.');
INSERT INTO public.sources (source_id, name, organisation, url, frequency, format, access, qualification_status, qualified_by, qualified_at, notes) VALUES ('cpb', 'World Trade Monitor', 'CPB Netherlands Bureau for Economic Policy Analysis', 'https://www.cpb.nl/en/worldtrademonitor/latest', 'mensuelle', 'Excel', 'libre', 'certifiee', 'N. Castillo', '2026-08-07 00:00:00+00', 'URL corrigée le 24.08.2026 : l''ancienne (…/en/worldtrademonitor) renvoyait 404. La nouvelle redirige vers le millésime courant.');
INSERT INTO public.sources (source_id, name, organisation, url, frequency, format, access, qualification_status, qualified_by, qualified_at, notes) VALUES ('sipri', 'Military Expenditure Database', 'SIPRI', 'https://www.sipri.org/databases/milex', 'annuelle', 'CSV', 'libre', 'certifiee', 'N. Castillo', '2026-08-07 00:00:00+00', 'URL corrigée le 24.08.2026 : l''ancienne (milex.sipri.org) échouait à la négociation TLS. Adresse alignée sur celle de la liaison S4.');
INSERT INTO public.sources (source_id, name, organisation, url, frequency, format, access, qualification_status, qualified_by, qualified_at, notes) VALUES ('ocde_brevets', 'Brevets par domaine technologique', 'OCDE', 'https://data-explorer.oecd.org/vis?df[ag]=OECD.STI.PIE&df[id]=DSD_PATENTS@DF_PATENTS_OECDSPECIFIC', 'annuelle', 'API SDMX', 'libre', 'certifiee', 'N. Castillo', '2026-08-25 00:00:00+00', 'Jeu DF_PATENTS_OECDSPECIFIC. Dix-huit domaines technologiques, dont MEDICAL et TRA (technologies de transport bas carbone). Sans clé. Vérifié en réponse réelle le 25.08.2026 : 13 points annuels 2010-2022, 106 zones disponibles.');
INSERT INTO public.sources (source_id, name, organisation, url, frequency, format, access, qualification_status, qualified_by, qualified_at, notes) VALUES ('ompi_tech', 'Indicateurs de brevets par domaine technologique', 'OMPI', 'https://www.wipo.int/en/web/ip-statistics', 'annuelle', 'ZIP / CSV', 'libre', 'certifiee', 'N. Castillo', '2026-08-25 00:00:00+00', 'Archive wipo-data-patent-indicators.zip, téléchargement direct sans inscription. Comptages par année, office, pays d''origine et domaine technologique (35 domaines). Vérifié en réponse réelle le 25.08.2026 : 663 584 lignes, 2000-2022. Table de concordance CIB/domaine publiée séparément et consultée pour établir les limites de granularité — G04 tombe dans « Techniques de mesure », B64 dans « Transport ».');
INSERT INTO public.sources (source_id, name, organisation, url, frequency, format, access, qualification_status, qualified_by, qualified_at, notes) VALUES ('cp', 'Recensement du personnel et des entreprises des industries horlogère et microtechnique suisses', 'Convention patronale de l''industrie horlogère suisse', 'https://cpih.ch/statistiques/', 'annuelle', 'PDF (lecture multimodale)', 'libre', 'certifiee', 'N. Castillo', '2026-08-30 00:00:00+00', 'Association patronale, PAS une statistique publique — provenance à déclarer comme pour la FH (§ 8.6.4) ; ne jamais étiqueter « donnée officielle ». Recensement au 30 septembre, publication en décembre. La page d''index est STABLE, le nom du PDF change chaque année : le lien se résout depuis l''index, comme pour la FH et le classeur SIPRI. Tableau Tb. 1e = série 2005-2025, effectifs et entreprises.');
INSERT INTO public.sources (source_id, name, organisation, url, frequency, format, access, qualification_status, qualified_by, qualified_at, notes) VALUES ('ted', 'Tenders Electronic Daily : marchés publics UE', 'Office des publications de l''UE', 'https://ted.europa.eu', 'quotidienne', 'API', 'libre', 'certifiee', 'N. Castillo', '2026-08-20 00:00:00+00', 'API de recherche v3, POST JSON, sans clé pour la recherche. Vérifiée en réponse réelle le 20.08.2026 (totalNoticeCount par requête CPV + bornes de dates). Source de la famille OSINT F3 (marchés publics) de la demande de ratification.');
INSERT INTO public.sources (source_id, name, organisation, url, frequency, format, access, qualification_status, qualified_by, qualified_at, notes) VALUES ('openfda', 'openFDA : bases publiques de la Food and Drug Administration', 'U.S. Food and Drug Administration', 'https://open.fda.gov', 'quotidienne', 'API', 'libre', 'certifiee', 'N. Castillo', '2026-08-23 00:00:00+00', 'API libre et sans clé (quota anonyme). Vérifiée en réponse réelle le 23.08.2026 : onze mois consécutifs de décomptes 510(k). Deux pièges d''appel consignés — la syntaxe d''intervalle « champ:[debut+TO+fin] » ne doit pas voir son « + » encodé (sinon 500), et une recherche sans résultat répond 404 et non 200 avec liste vide.');
INSERT INTO public.sources (source_id, name, organisation, url, frequency, format, access, qualification_status, qualified_by, qualified_at, notes) VALUES ('triage_flux', 'Intensité de signalement dans les flux qualifiés (dérivation interne)', 'Dispositif de veille : dérivation du triage IA (v_intensite_signalement)', 'interne : flux_sources → flux_items → flux_triage_ia → v_intensite_signalement', 'mensuelle', 'sql', 'libre', 'a_confirmer', 'N. Castillo (délégation du 27.08.2026)', '2026-08-27 19:04:35.041206+00', 'Non pas une source externe mais une dérivation : part mensuelle des items triés attribués à une question de veille. Hérite de la qualification des flux sous-jacents (tous en accès libre). a_confirmer tant que le corpus est jeune (démarré fin 07.2026) et sa composition mouvante.');
INSERT INTO public.sources (source_id, name, organisation, url, frequency, format, access, qualification_status, qualified_by, qualified_at, notes) VALUES ('acea_incitations', 'Electric cars: tax benefits and incentives (fiscalité et aides à l''achat, par pays)', 'ACEA', 'https://www.acea.auto/fact/electric-cars-tax-benefits-and-incentives-2025/', 'annuelle', 'PDF tabulaire (tableau comparatif par pays)', 'libre', 'a_confirmer', 'N. Castillo', '2026-09-02 12:56:58.411677+00', 'Issue de la couche 0 (run du 22.08.2026, QV5 automobile, candidat 2, 3 modèles sur 4). Inscrite le 02.09.2026 sans liaison de collecte : accès vérifié en réponse réelle (HTTP 200 les 22.08 et 02.09), granularité d''extraction non validée. Pas d''indicateur rattaché à ce jour.');
INSERT INTO public.sources (source_id, name, organisation, url, frequency, format, access, qualification_status, qualified_by, qualified_at, notes) VALUES ('oica', 'Production mondiale de véhicules par pays — tableau republié dans l''annuaire du CCFA « L''industrie automobile française » (mention imprimée « Source : OICA »), document collecté ; classements top-10 de la page OICA en vérité terrain', 'OICA', 'https://www.oica.net/production-statistics', 'annuelle', 'PDF (annuaire CCFA, https://ccfa.fr/analyses-et-statistiques/) ; tableaux web OICA pour la confrontation opportuniste', 'libre', 'certifiee', 'N. Castillo', '2026-08-31 00:00:00+00', 'Producteur : OICA. Document collecté : annuaire CCFA (association professionnelle française), PDF, une édition par an, tableau « La production mondiale de véhicules » par pays en milliers, mention « Source : OICA » imprimée. Éditions traitées au 31.08.2026 : page des analyses et statistiques (édition courante), CCFA-2023, CCFA-2024 (composite_queue 9-11), série 2021-2024. Découpe par sentinelles avant envoi aux modèles (~1 % du document : 5 100 caractères sur ~530 000, mesuré sur les exécutions du 31.08.2026 ; corrigé de 2,5 % le 04.09). Vérité terrain de rang 1 : classements top-10 de https://www.oica.net/production-statistics, JSON incorporé, confrontation opportuniste (non_verifiable quand l''année n''est pas servie, jamais de faux verdict). Détection des nouvelles éditions : workflow veille_documentaire_annuelle.');
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('S9', 'aerospatial', 'Intensité de signalement : dynamique technologique (triage IA des flux)', 'triage_flux', 'composite', 'mensuelle', 'pourcentage', 'a_confirmer', NULL, '2026-08-27 19:04:35.041206+00', 'Part des signaux du mois (presse spécialisée, actualité, marchés publics) que l''IA de triage rattache à la dynamique technologique du secteur : procédés, matériaux, architectures en substitution. Une part qui monte signale une recomposition technique en cours, celle que les statistiques de production ne montrent qu''après coup.', 0, 'avance', 'WORLD', true, 'Créé le 27.08.2026 (décision de l''étudiant, revue du 26-27.08). Premier porteur de la case aérospatial × QV4 (dominante), vide en vitrine depuis la scission de QV3. Admission par critère de rôle, statut a_confirmer : série d''un point (2026-08 : 21/124 items). Plancher de calculabilité 20 items/mois, part et non compte (corpus en croissance). Modèle de triage unique → consensus non établi → validation humaine systématique.', 1.0, NULL);
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('T3', 'transversal', 'Commerce mondial de marchandises (volume)', 'cpb', 'hard', 'mensuelle', 'indice', 'certifie', 3, '2026-08-06 09:02:40.226196+00', 'Volume du commerce mondial de marchandises (CPB) : le débit réel des flux dont dépendent les quatre secteurs.', 1, 'coincident', 'WORLD', true, NULL, NULL, NULL);
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('A2', 'automobile', 'Immatriculations de voitures particulières neuves, UE27 (ACEA)', 'acea', 'composite', 'mensuelle', 'unités', 'certifie', 5, '2026-08-06 09:02:40.226196+00', 'Immatriculations mensuelles de voitures particulières neuves dans l''Union européenne (ligne « EUROPEAN UNION » du communiqué ACEA, geo EU27) : la demande finale, en aval de la chaîne dont dépend un fournisseur de composants. Voitures particulières seulement — ni utilitaires, ni marchés hors UE.', 1, 'coincident', 'EU27', true, NULL, 1.0, NULL);
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('T2', 'transversal', 'Taux de change CHF/USD et CHF/EUR', 'bns', 'hard', 'mensuelle', 'taux', 'certifie', 7, '2026-08-06 09:02:40.226196+00', 'Taux de change moyens mensuels : un franc plus fort renchérit les exportations facturées en euros et en dollars : la variable la plus directe sur la marge d''un exportateur.', 1, 'coincident', 'CHF_EUR', true, NULL, NULL, NULL);
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('A3', 'automobile', 'Ventes mondiales de véhicules électriques par pays', 'aie', 'hard', 'annuelle', 'unités', 'certifie', 10, '2026-08-06 09:02:40.226196+00', 'Ventes de véhicules électriques par pays : la recomposition technologique et géographique de la demande automobile.', 0, 'coincident', 'World', true, 'HORS VITRINE le 25.08.2026 — moins de douze points sur la zone de référence : la série ne se lit pas.
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('H7', 'horlogerie', 'Exportations suisses de montres-bracelets, valeur (FH)', 'fh', 'hard', 'mensuelle', 'mio CHF', 'certifie', 8, '2026-08-24 14:39:23.570068+00', 'La mesure de référence du débouché horloger, en francs — MONTRES-BRACELETS seulement : le tableau FH lu par le collecteur est celui des montres-bracelets (total, électroniques, mécaniques), non l''ensemble du chapitre SH 91 (mouvements, composants, horloges). H1 (Comtrade, chapitre entier) converti en francs lui est supérieur de 4 à 5 % chaque mois, écart régulier de périmètre et non contradiction entre sources. Remplace fonctionnellement la lecture en dollars de H1, dont la corrélation au taux CHF/USD a été mesurée à -0,40 : un sixième de sa variance était du change. Publiée à J+20 par la Fédération, à partir des statistiques douanières fédérales.', 1, 'coincident', 'CH', true, NULL, NULL, NULL);
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('M4', 'medical', 'Emplois medtech et mécanique de précision en Suisse (NOGA 26.6, 32.5 — y c. mécaniciens-dentistes et lunetterie)', 'ofs', 'hard', 'annuelle', 'nombre', 'certifie', 5, '2026-08-06 09:02:40.226196+00', 'Emplois (et non établissements) des cinq genres NOGA 266000, 325001, 325002, 325003 et 325004, Suisse entière, STATENT : la substance productive nationale du secteur. Le périmètre inclut deux activités non industrielles — mécaniciens-dentistes (325003) et fabrication de lunettes (325004), 15,9 % du total 2024 (5 254 sur 33 104, vérifié sur le brut du run 212) ; les exclure changerait la définition sous le même identifiant, ce qui se décide en supervision, pas dans un libellé.', 1, 'retarde', 'CH', true, 'ÉTAT AU 24.08.2026 : un seul point au registre. L''indicateur ne produira aucune lecture exploitable avant plusieurs exercices, et n''entre dans aucun calcul. Conservé au référentiel parce que la grille décrit ce que le dispositif est conçu pour suivre ; son inactivité est une limite déclarée, non un oubli.
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('M8', 'medical', 'Autorisations FDA 510(k) de dispositifs médicaux (États-Unis)', 'openfda', 'hard', 'mensuelle', 'nombre d''autorisations', 'certifie', NULL, '2026-08-23 14:29:40.475286+00', 'Le nombre de dispositifs médicaux autorisés chaque mois à la mise sur le marché américain. Un acte réglementaire précède la production en série, donc la commande de pièces usinées : l''indicateur est avancé par construction. Se lit en tendance, un décompte d''autorisations n''est ni un volume ni un chiffre d''affaires, et le périmètre est américain, non mondial.', 1, 'avance', 'US', true, 'SEUIL NON CALIBRABLE À CE JOUR, ÉNONCÉ (constat du 31.08.2026). Aucun glissement annuel n''est calculable sur cette série : elle n''a pas encore d''homologue à douze mois. Le seuil reste absent jusqu''à ce que l''historique le permette — il n''est pas posé par défaut, un seuil semé mais jamais confronté aux données n''étant qu''une valeur plausible. À reprendre lorsque la série atteindra deux cycles annuels.', NULL, NULL);
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('T6', 'transversal', 'Baromètre conjoncturel KOF (Suisse)', 'kof', 'hard', 'mensuelle', 'indice', 'certifie', 15, '2026-08-17 17:34:28.137917+00', 'Indicateur avancé de l''économie suisse (ETH Zurich) : anticipe la conjoncture à environ six mois. Le pouls de l''écosystème dans lequel opère une PME industrielle neuchâteloise.', 1, 'avance', 'CH', true, NULL, NULL, NULL);
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('S8', 'aerospatial', 'Production aéronautique et spatiale UE (NACE C30.3)', 'eurostat', 'hard', 'mensuelle', 'indice', 'certifie', 6, '2026-08-24 13:42:17.199995+00', 'L''activité de la branche cliente. Le secteur aérospatial n''était instrumenté que par des flux de commerce, des dépenses militaires et un décompte d''objets lancés, aucune mesure de ce que la branche PRODUIT, donc de ce qu''elle commande.', 1, 'coincident', 'EU27_2020', true, NULL, NULL, NULL);
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('T5', 'transversal', 'Attentes de production de l''industrie européenne (solde d''opinion à 3 mois)', 'eurostat', 'hard', 'mensuelle', 'solde d''opinion', 'certifie', NULL, '2026-08-17 17:34:28.137917+00', 'Enquête de conjoncture DG ECFIN : ce que les industriels européens prévoient de produire dans les trois prochains mois. Indicateur avancé par construction, il précède les volumes, là où les statistiques consolidées les constatent.', 1, 'avance', 'EU27_2020', true, 'MATÉRIALITÉ EN POURCENTAGE INAPPLICABLE, ÉNONCÉE (arbitrage du 31.08.2026). La série est un solde d''opinion : elle admet des valeurs négatives et passe par zéro (T8 : 119 valeurs négatives sur 139 ; T5 : 6 sur 140). Un glissement exprimé en pourcentage y produit des artefacts — maximum observé 18 200 % pour T8, 19 300 % pour T5 — qui décrivent le franchissement de zéro, non un événement conjoncturel. C''est la conséquence arithmétique du drapeau admet_negatifs déjà déclaré sur cette liaison. Aucun seuil n''est donc posé : RI4 est inapplicable à cette série, et le dispositif le dit plutôt que d''alerter sur du bruit. Un seuil exprimé en POINTS serait l''instrument juste ; il est documenté comme perspective, non implémenté dans cette itération.', NULL, NULL);
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('H12', 'horlogerie', 'Emplois horlogers suisses (STATENT, NOGA 26.52)', 'ofs', 'hard', 'annuelle', 'nombre', 'certifie', 5, '2026-08-30 21:09:34.766784+00', 'Emploi de la seule fabrication de montres et d''horloges (NOGA 26.52), mesuré par la statistique publique. Série de COMPARAISON DE PÉRIMÈTRE face à H2 : même grandeur, périmètre plus étroit.', 1, 'retarde', 'CH', false, 'Créé le 30.08.2026 pour porter la collecte STATENT sous son propre nom, quand H2 est passé au recensement de la Convention patronale. Les 56 observations STATENT antérieures n''ont PAS été déplacées : le registre est en ajout seul (D-18) et le déclencheur a refusé la réattribution. Elles restent sous H2 comme histoire d''avant la redéfinition ; H12 se remplit par collecte, la liaison lui ayant été transférée.
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('T9', 'transversal', 'Taux d''utilisation des capacités de l''industrie UE', 'eurostat', 'hard', 'trimestrielle', 'pourcentage', 'certifie', 4.5, '2026-08-24 13:42:17.199995+00', 'Mesure la marge de production disponible dans la branche. Un taux élevé annonce des investissements et des reports de charge vers la sous-traitance ; un taux bas signale que les donneurs d''ordre peuvent internaliser ce qu''ils sous-traitaient. C''est le mécanisme du « faire ou faire faire » (§ 5.5), rendu observable.', 1, 'coincident', 'EU27_2020', true, NULL, NULL, NULL);
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('H11', 'horlogerie', 'Entreprises de la branche horlogère et microtechnique suisse (recensement CP)', 'cp', 'composite', 'annuelle', 'nombre', 'a_confirmer', 5, '2026-08-30 21:09:34.766784+00', 'Nombre d''entités locales exerçant une activité horlogère ou microtechnique en Suisse, recensées au 30 septembre. Le tissu lui-même, et non son volume d''emploi : une branche peut gagner des emplois en perdant des ateliers, c''est exactement le mécanisme que la question de veille QV1 surveille.', 1, 'coincident', 'CH', true, 'Créé le 30.08.2026, extrait du MÊME tableau et de la MÊME extraction que H2 (colonne « Entreprises » de Tb. 1e) : aucun appel supplémentaire.
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('T7', 'transversal', 'Production de l''usinage et du traitement des métaux UE (NACE C25.6)', 'eurostat', 'hard', 'mensuelle', 'indice', 'certifie', 10, '2026-08-20 20:21:42.436622+00', 'L''activité du métier lui-même : la production européenne de traitement, revêtement et usinage des métaux, le code NACE de la sous-traitance mécanique de précision. Quand un marché client bouge, cet indice dit si c''est le secteur qui bouge ou toute la profession. Le chaînon entre la conjoncture des marchés finaux et le carnet d''un décolleteur.', 1, 'coincident', 'EU27_2020', true, NULL, NULL, NULL);
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('T11', 'transversal', 'Production manufacturière suisse (NACE C)', 'eurostat', 'hard', 'mensuelle', 'indice', 'certifie', 5, '2026-08-24 13:42:17.199995+00', 'L''activité industrielle de l''écosystème du cas d''illustration. La ventilation par branche n''est pas disponible pour la Suisse dans cette source : la série existe pour l''ensemble manufacturier et pour lui seul. Sert de repère national face à l''agrégat européen.', 1, 'coincident', 'CH', true, 'Absence de ventilation par branche pour la Suisse vérifiée le 24.08.2026 chez le producteur.', NULL, NULL);
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('A10', 'automobile', 'Intensité de signalement : impulsions publiques (triage IA des flux)', 'triage_flux', 'composite', 'mensuelle', 'pourcentage', 'a_confirmer', NULL, '2026-08-27 19:04:35.041206+00', 'Part des signaux du mois que l''IA de triage rattache à l''action publique sur l''automobile : normes d''émissions, subventions à l''achat, droits de douane, plans de soutien. L''action publique y déplace la demande à moyen terme plus sûrement que la conjoncture.', 0, 'avance', 'WORLD', true, 'Créé le 27.08.2026. Premier porteur de la case automobile × QV5 (dominante). Mêmes règles que S9. Série : 2026-07 (2/21), 2026-08 (17/101).', 1.0, NULL);
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('H10', 'horlogerie', 'Intensité de signalement : dynamique technologique (triage IA des flux)', 'triage_flux', 'composite', 'mensuelle', 'pourcentage', 'a_confirmer', NULL, '2026-08-27 19:04:35.041206+00', 'Part des signaux du mois que l''IA de triage rattache à la dynamique technologique horlogère : matériaux, procédés, complications, fabrication additive.', 0, 'avance', 'WORLD', true, 'Créé le 27.08.2026. Porteur DÉCLARÉ SANS POINT CALCULABLE de la case horlogerie × QV4 : le corpus horloger d''août 2026 compte 16 items triés, sous le plancher de 20. La case reste vide avec une raison mesurée — le corpus de flux horloger est mince (2 fils de presse + actualité) — et l''indicateur s''activera quand le corpus franchira le plancher, sans changement de définition. Distinct du cas H5 (couverture nominale, § 8.4.5) : ici la machinerie tourne et la raison du vide est chiffrée.', 1.0, NULL);
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('A9', 'automobile', 'Intensité de signalement : dynamique technologique (triage IA des flux)', 'triage_flux', 'composite', 'mensuelle', 'pourcentage', 'a_confirmer', NULL, '2026-08-27 19:04:35.041206+00', 'Part des signaux du mois que l''IA de triage rattache à la dynamique technologique automobile : électrification, batteries, procédés de fabrication. Pour un fournisseur de composants mécaniques, c''est la question vitale, l''électrification supprime des familles entières de pièces usinées.', 0, 'avance', 'WORLD', true, 'Créé le 27.08.2026. Premier porteur de la case automobile × QV4 (dominante). Mêmes règles que S9. Série : 2026-07 (1/21), 2026-08 (18/101). Complète A7 (brevets bas carbone, certifié, hors vitrine) : A7 mesure l''amont long des dépôts, A9 le présent du signalement.', 1.0, NULL);
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('T8', 'transversal', 'État du carnet de commandes de l''industrie UE (enquête de conjoncture)', 'eurostat', 'hard', 'mensuelle', 'solde', 'certifie', NULL, '2026-08-24 13:42:17.199995+00', 'Le signal d''avance du carnet de commandes. Solde d''opinion des industriels sur l''état de leur carnet, publié à J+0 sans révision : un carnet qui se dégarnit précède la baisse de production de plusieurs mois, c''est la variable que lit un directeur d''atelier avant toute statistique. Grandeur intensive et légitimement négative : ne jamais la sommer. Se lit en POINTS et en niveau, jamais en pourcentage, le solde traverse zéro, et la variation relative y inverse le sens économique.', 1, 'avance', 'EU27_2020', true, 'PIÈGE DE LECTURE, DÉCLARÉ : le carnet européen est passé de -26,7 à -17,5 entre juillet 2025 et juillet 2026 — une amélioration — que le calcul relatif exprimait en -34,5 % avant la correction du 01.09.2026 (dénominateur en valeur absolue : la direction est désormais exacte, l''ampleur reste à lire en points). Le seuil de matérialité est laissé nul à dessein, ce qui rend la règle RI4 inapplicable et interdit au modèle de commenter la variation.
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('A1', 'automobile', 'Production mondiale de véhicules par pays', 'oica', 'composite', 'annuelle', 'unités', 'certifie', 5, '2026-08-06 09:02:40.226196+00', 'Production mondiale de véhicules par pays : le volume et la géographie de l''assemblage automobile.', 1, 'retarde', 'World', true, 'HORS VITRINE le 25.08.2026 — aucune observation collectée : la source est qualifiée, la liaison manque ou l''accès n''a pas été obtenu.
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('A11', 'automobile', 'Part électrique des ventes mondiales de voitures (IEA)', 'aie', 'hard', 'annuelle', 'pourcentage', 'certifie', NULL, '2026-08-27 19:54:22.122171+00', 'Part des voitures électriques (BEV, PHEV, FCEV) dans les ventes mondiales de voitures neuves, telle que publiée par l''Agence internationale de l''énergie. C''est la mesure directe de la substitution de motorisation : pour un fournisseur de composants mécaniques, chaque point de part gagné par l''électrique déplace la demande de familles entières de pièces, la question QV4 en un chiffre.', 0, 'coincident', 'World', true, 'Créé le 27.08.2026 (décision de l''étudiant). Valeur collectée telle quelle — la part est calculée par la source, aucune dérivation de notre part. Réponse réelle vérifiée sur 2010/2015/2020/2024. Liaisons semées sur 2010-2025 (une par millésime, l''API exige year) ; la fenêtre d''historique des séries annuelles (2014) sert 12 points — 2010-2013 sont décodés puis écartés « hors fenêtre », et comptés. Sens neutre : la recomposition n''est ni favorable ni défavorable en soi pour la sous-traitance. Complète A9 (intensité de signalement QV4) : A9 mesure ce dont le marché parle, A11 ce qu''il fait. Le total mondial et le volume thermique s''en dérivent par vue (v_motorisations_automobile).
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('M7', 'medical', 'Avis de marchés publics UE en équipements médicaux (TED, CPV 33)', 'ted', 'hard', 'mensuelle', 'nombre d''avis', 'certifie', NULL, '2026-08-20 20:21:42.766289+00', 'La demande publique adressée au secteur médical, comptée à la source : le nombre d''avis de marchés publiés chaque mois au journal des marchés publics européens pour des équipements et fournitures médicaux. En amont des commandes et des flux commerciaux, à fraîcheur immédiate. Se lit en tendance, un décompte d''avis n''est pas un volume en francs.', 1, 'avance', 'EU', true, 'SEUIL NON CALIBRABLE À CE JOUR, ÉNONCÉ (constat du 31.08.2026). Aucun glissement annuel n''est calculable sur cette série : elle n''a pas encore d''homologue à douze mois. Le seuil reste absent jusqu''à ce que l''historique le permette — il n''est pas posé par défaut, un seuil semé mais jamais confronté aux données n''étant qu''une valeur plausible. À reprendre lorsque la série atteindra deux cycles annuels.', NULL, NULL);
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('H3', 'horlogerie', 'Commerce mondial d''articles d''horlogerie (SH ch. 91), par pays', 'comtrade', 'hard', 'annuelle', 'USD', 'certifie', 10, '2026-08-06 09:02:40.226196+00', 'Exportations annuelles d''articles d''horlogerie par pays : la place de chaque économie dans le commerce horloger mondial, Suisse comprise.', 1, 'retarde', 'CHE', true, NULL, NULL, NULL);
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('M1', 'medical', 'Commerce mondial d''instruments médicaux (SH 9018-9022), par pays', 'comtrade', 'hard', 'annuelle', 'USD', 'certifie', 12, '2026-08-06 09:02:40.226196+00', 'Exportations annuelles d''instruments médicaux par pays (SH 9018-9022) : la géographie de l''offre mondiale en technologies médicales.', 1, 'retarde', 'CHE', true, NULL, NULL, NULL);
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('S4', 'aerospatial', 'Dépenses militaires par pays', 'sipri', 'hard', 'annuelle', 'mio USD', 'certifie', 5, '2026-08-06 09:02:40.226196+00', 'Dépenses militaires par pays : en aérospatial-défense, le budget public est la demande elle-même.', 1, 'avance', 'USA', true, NULL, NULL, NULL);
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('H1', 'horlogerie', 'Exportations horlogères suisses par marché de destination', 'comtrade', 'hard', 'mensuelle', 'USD', 'certifie', 25, '2026-08-06 09:02:40.226196+00', 'Exportations horlogères suisses par pays de destination, en valeur mensuelle : où la demande se porte, où elle se retire.', 1, 'coincident', 'W00', true, NULL, NULL, NULL);
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('A5', 'automobile', 'Production industrielle automobile UE (NACE C29)', 'eurostat', 'hard', 'mensuelle', 'indice', 'certifie', 10, '2026-08-06 09:02:40.226196+00', 'Indice mensuel de production automobile de l''UE (base 2021 = 100) : l''activité réelle des usines clientes.', 1, 'coincident', 'EU27_2020', true, NULL, NULL, NULL);
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('A4', 'automobile', 'Commerce mondial de parties et accessoires automobiles (SH 8708)', 'comtrade', 'hard', 'annuelle', 'USD', 'certifie', 10, '2026-08-06 09:02:40.226196+00', 'Exportations de parties et accessoires automobiles par pays (SH 8708) : qui fournit la chaîne mondiale, et où les flux se déplacent.', 1, 'retarde', 'DEU', true, NULL, NULL, NULL);
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('T1', 'transversal', 'Indicateur composite avancé (CLI), zone G20', 'ocde', 'hard', 'mensuelle', 'indice', 'certifie', 0.5, '2026-08-06 09:02:40.226196+00', 'Indicateur avancé de l''OCDE (zone G20) : au-dessus de 100, l''activité des grandes économies tend à accélérer dans les six à neuf mois ; en dessous, à ralentir.', 1, 'avance', 'G20', true, NULL, NULL, NULL);
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('S6', 'aerospatial', 'Commerce mondial aéronautique et spatial (SH ch. 88)', 'comtrade', 'hard', 'annuelle', 'USD', 'certifie', 20, '2026-08-06 09:02:40.226196+00', 'Exportations aéronautiques et spatiales par pays (SH ch. 88) : la géographie du commerce du secteur.', 1, 'retarde', 'FRA', true, NULL, NULL, NULL);
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('H6', 'horlogerie', 'Production horlogère UE (NACE C26.52)', 'eurostat', 'hard', 'mensuelle', 'indice', 'certifie', 6, '2026-08-24 13:42:17.199995+00', 'L''activité de la branche cliente elle-même, et non ses exportations. Une exportation est une valeur en monnaie, sensible au change et au mix de gamme ; un indice de production mesure le VOLUME fabriqué, qui commande directement la charge d''usinage. Le secteur horloger ne disposait jusqu''ici que de flux de commerce et d''un point d''emploi de 2023.', 1, 'coincident', 'EU27_2020', true, NULL, NULL, NULL);
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('S7', 'aerospatial', 'Avis de marchés publics UE en aéronefs et engins spatiaux (TED, CPV 347)', 'ted', 'hard', 'mensuelle', 'nombre d''avis', 'certifie', NULL, '2026-08-23 14:29:40.475286+00', 'La demande publique adressée au secteur aérospatial, comptée à la source. Transposition de la méthode de M7 au CPV 34700000. Le secteur où elle a le plus de sens : dans l''aérospatial, l''acheteur public, armées, agences spatiales, EST une part majeure du marché, ce qui n''est pas le cas de l''automobile. Se lit en tendance.', 1, 'avance', 'EU', true, 'SEUIL NON CALIBRABLE À CE JOUR, ÉNONCÉ (constat du 31.08.2026). Aucun glissement annuel n''est calculable sur cette série : elle n''a pas encore d''homologue à douze mois. Le seuil reste absent jusqu''à ce que l''historique le permette — il n''est pas posé par défaut, un seuil semé mais jamais confronté aux données n''étant qu''une valeur plausible. À reprendre lorsque la série atteindra deux cycles annuels.', NULL, NULL);
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('M2', 'medical', 'Production d''instruments et fournitures médicales et dentaires UE (NACE C32.5)', 'eurostat', 'hard', 'mensuelle', 'indice', 'certifie', 12, '2026-08-06 09:02:40.226196+00', 'Production de l''industrie des instruments médicaux de l''UE (indice mensuel) : l''activité réelle des usines de la branche.', 1, 'coincident', 'EU27_2020', true, NULL, NULL, NULL);
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('H2', 'horlogerie', 'Emploi de la branche horlogère et microtechnique suisse (recensement CP)', 'cp', 'composite', 'annuelle', 'nombre', 'certifie', 5, '2026-08-06 09:02:40.226196+00', 'Effectifs occupés par les industries horlogère et microtechnique suisses, recensés chaque année au 30 septembre par la Convention patronale. Le périmètre inclut la microtechnique, donc les ateliers de mécanique de précision qui travaillent pour l''horlogerie sans être classés en NOGA 26.52, la réalité d''un sous-traitant comme le cas d''illustration.', 1, 'coincident', 'CH', true, 'REDÉFINI le 30.08.2026 : source OFS/STATENT → recensement de la Convention patronale ; catégorie hard → composite ; périmètre NOGA 26.52 → horlogerie et microtechnique. Les 56 observations STATENT antérieures (runs 43-161) RESTENT sous H2 : le registre est en ajout seul (D-18) et le déclencheur a refusé la réattribution. Elles sont l''histoire d''avant la redéfinition ; la collecte STATENT se poursuit sous H12, qui a reçu la liaison. La note disait jusqu''au 02.09 « réattribuées à H12 » : c''était faux, H12 disait vrai.
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('A6', 'automobile', 'Production d''équipements automobiles UE (NACE C29.3)', 'eurostat', 'hard', 'mensuelle', 'indice', 'certifie', 6, '2026-08-24 13:42:17.199995+00', 'La demande adressable de la sous-traitance automobile, à l''étage où elle s''exprime. C29.3 est la fabrication d''équipements pour véhicules, le métier des donneurs d''ordre d''un atelier d''usinage. À comparer systématiquement à A5 (C29, fabrication de véhicules) : l''écart entre les deux mesure la transmission du marché final vers la sous-traitance, et un écart qui se creuse signale que le marché final ne se transmet plus.', 1, 'coincident', 'EU27_2020', true, NULL, NULL, NULL);
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('T10', 'transversal', 'Part des industriels déclarant la demande comme facteur limitant (UE)', 'eurostat', 'hard', 'trimestrielle', 'pourcentage', 'certifie', NULL, '2026-08-24 13:42:17.199995+00', 'Un signal précoce de retournement. Part des entreprises citant l''insuffisance de la demande parmi les freins à leur production : elle monte avant que les carnets ne se vident, et bien avant que la production ne recule. Sens inversé, une hausse est défavorable. Se lit en POINTS et en niveau, jamais en pourcentage, le solde traverse zéro, et la variation relative y inverse le sens économique.', -1, 'avance', 'EU27_2020', true, 'PIÈGE DE LECTURE, DÉCLARÉ : le carnet européen est passé de -26,7 à -17,5 entre juillet 2025 et juillet 2026 — une amélioration — que le calcul relatif exprimait en -34,5 % avant la correction du 01.09.2026 (dénominateur en valeur absolue : la direction est désormais exacte, l''ampleur reste à lire en points). Le seuil de matérialité est laissé nul à dessein, ce qui rend la règle RI4 inapplicable et interdit au modèle de commenter la variation.
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('M6', 'medical', 'Brevets en technologie médicale, dépôts à l''OEB (OCDE)', 'ocde_brevets', 'hard', 'annuelle', 'nombre', 'certifie', 20, '2026-08-06 09:02:40.226196+00', 'La position technologique de la branche médicale, et non son activité. Comptage des dépôts de brevets en technologie médicale, par pays du déposant. Un brevet précède le produit de plusieurs années : il renseigne sur ce qui se prépare, pas sur ce qui se vend, donc, pour un sous-traitant, sur le rythme auquel les plans, tolérances et matériaux qu''on lui demandera vont changer. Ne se lit pas en conjoncture : le dernier point disponible est 2022.', 0, 'retarde', 'CHE', false, 'Zone de référence CHE : ce qui intéresse un atelier neuchâtelois est la vitalité technologique de son écosystème.
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('A7', 'automobile', 'Brevets en technologies de transport bas carbone (OCDE)', 'ocde_brevets', 'hard', 'annuelle', 'nombre', 'certifie', 38, '2026-08-24 15:52:54.712996+00', 'Ce qui recompose la demande de composants, à la racine. A3 mesure les ventes de véhicules électriques, c''est-à-dire le résultat, plusieurs années après la décision technique ; le comptage de brevets en technologies de transport bas carbone mesure la décision elle-même, au moment où elle est prise. Un basculement de l''effort de R&D précède de cinq à dix ans le changement des familles de pièces commandées. Ne se lit pas en conjoncture : le dernier point disponible est 2022.', 0, 'retarde', 'DEU', false, 'Zone de référence DEU — premier déposant européen et premier débouché de la sous-traitance automobile suisse.
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('A8', 'automobile', 'Avis de marchés publics UE en pièces mécaniques automobiles (TED, CPV 34.31/34.32)', 'ted', 'hard', 'mensuelle', 'nombre d''avis', 'a_confirmer', NULL, '2026-08-25 19:05:59.726669+00', 'La demande publique adressée aux pièces mécaniques automobiles, comptée à la source : le nombre d''avis de marchés publiés chaque mois au journal des marchés publics européens pour des moteurs et des pièces de rechange. En amont des commandes et des flux commerciaux, à fraîcheur immédiate, un avis publié aujourd''hui concerne une production à six ou dix-huit mois. Ne mesure que la part publique de la demande automobile : se lit en tendance, jamais en volume.', 1, 'avance', 'EU', false, 'HORS VITRINE le 25.08.2026 — aucune observation collectée : la source est qualifiée, la liaison manque ou l''accès n''a pas été obtenu.', NULL, NULL);
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('H4', 'horlogerie', 'Dépôts de brevets en horlogerie (CIB G04)', 'ompi', 'hard', 'annuelle', 'nombre', 'certifie', 10, '2026-08-06 09:02:40.226196+00', 'Dépôts de brevets en horlogerie (CIB G04) : où l''effort d''innovation du secteur se localise.', 1, 'avance', NULL, false, 'HORS VITRINE le 25.08.2026 — aucune observation collectée : la source est qualifiée, la liaison manque ou l''accès n''a pas été obtenu.', NULL, NULL);
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('H8', 'horlogerie', 'Exportations de montres mécaniques, valeur (FH)', 'fh', 'hard', 'mensuelle', 'mio CHF', 'certifie', 8, '2026-08-24 14:39:23.570068+00', 'La part usinée du débouché horloger. Une montre mécanique mobilise des dizaines de pièces usinées à tolérances serrées ; une montre à quartz en mobilise peu. C''est donc cette série, et non la valeur horlogère totale, qui commande la charge d''un atelier de décolletage. À lire avec H7 : leur rapport est le mix.', 0, 'coincident', 'CH', false, 'RETIRÉ DU SCORE le 24.08.2026 : corrélation des résidus détendancés de 0,993 avec H7 — c''est la même série, issue du même tableau. Le compter au score donnerait trois voix à une seule mesure. Reste lu par la vue v_mix_horloger, qui exploite son rapport à H7 et non son niveau.
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('H5', 'horlogerie', 'Climat de branche et perspectives', 'deloitte', 'composite', 'annuelle', 'qualitatif', 'a_confirmer', NULL, '2026-08-06 09:02:40.226196+00', 'Climat de branche et perspectives déclarées par les acteurs (étude annuelle) : le qualitatif qui précède parfois les chiffres.', NULL, NULL, NULL, false, 'HORS VITRINE le 25.08.2026 — aucune observation collectée : la source est qualifiée, la liaison manque ou l''accès n''a pas été obtenu.', 1.0, NULL);
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('H9', 'horlogerie', 'Exportations de montres mécaniques, volume (FH)', 'fh', 'hard', 'mensuelle', 'milliers de pièces', 'certifie', 8, '2026-08-24 14:39:23.570068+00', 'Le volume mécanique, distinct de sa valeur. Un atelier facture des pièces, pas des francs : une montée en gamme peut accroître la valeur exportée sans accroître le nombre de montres produites, donc sans accroître la charge d''usinage. C''est le point de vigilance qu''énonce QV1, une montée en valeur qui masquerait l''érosion du tissu de sous-traitance, et H9 le rend observable.', 0, 'coincident', 'CH', true, 'RETIRÉ DU SCORE le 24.08.2026 : corrélation des résidus de 0,910 avec H7. Reste l''une des deux jambes du mix mécanique, où sa valeur est entière — c''est l''écart entre volume et valeur qui informe, pas le niveau du volume pris seul.', NULL, NULL);
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('S1', 'aerospatial', 'Commandes et livraisons d''avions commerciaux (Airbus, Boeing)', 'constructeurs', 'hard', 'mensuelle', 'appareils', 'certifie', 10, '2026-08-06 09:02:40.226196+00', 'Commandes et livraisons d''avions commerciaux (Airbus, Boeing) : le carnet qui engage la sous-traitance sur plusieurs années.', 1, 'avance', NULL, false, 'HORS VITRINE le 25.08.2026 — aucune observation collectée : la source est qualifiée, la liaison manque ou l''accès n''a pas été obtenu.', NULL, NULL);
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('S3', 'aerospatial', 'Objets lancés dans l''espace par pays', 'unoosa', 'hard', 'annuelle', 'nombre', 'certifie', 80, '2026-08-06 09:02:40.226196+00', 'Objets lancés dans l''espace par pays : l''activité spatiale effective. Série volatile par nature, à lire en tendance.', 0, 'retarde', 'OWID_WRL', true, 'RETIRÉ DU SCORE le 24.08.2026 : contribution mesurée de +1,98, la plus forte de la grille, pour une série qui compte des lancements de satellites. Un atelier d''usinage de précision suisse n''en usine pas : le nombre d''objets lancés ne commande aucune charge chez lui. L''indicateur pilotait le score aérospatial sans rapport avec ce que ce score prétend mesurer. Conservé pour QV3, où sa lecture géographique reste légitime.', NULL, NULL);
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('M5', 'medical', 'Panorama de la branche medtech suisse', 'swiss_medtech', 'composite', 'bisannuelle', 'mia CHF', 'a_confirmer', NULL, '2026-08-06 09:02:40.226196+00', 'Panorama bisannuel de la branche medtech suisse : cadrage qualitatif et chiffres de référence.', NULL, NULL, NULL, false, 'HORS VITRINE le 25.08.2026 — aucune observation collectée : la source est qualifiée, la liaison manque ou l''accès n''a pas été obtenu.', 1.0, NULL);
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('S2', 'aerospatial', 'Trafic aérien mondial de passagers (RPK)', 'iata', 'composite', 'mensuelle', 'indice', 'a_confirmer', NULL, '2026-08-06 09:02:40.226196+00', 'Trafic aérien mondial de passagers (RPK) : la demande de transport qui commande les cadences de production.', NULL, NULL, NULL, false, 'HORS VITRINE le 25.08.2026 — aucune observation collectée : la source est qualifiée, la liaison manque ou l''accès n''a pas été obtenu.', 1.0, NULL);
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('S5', 'aerospatial', 'Budget de l''ESA et budgets spatiaux publics', 'esa', 'composite', 'annuelle', 'mio EUR', 'a_confirmer', NULL, '2026-08-06 09:02:40.226196+00', 'Budgets spatiaux publics (ESA et agences nationales) : l''impulsion publique qui finance les programmes.', NULL, NULL, NULL, false, 'HORS VITRINE le 25.08.2026 — aucune observation collectée : la source est qualifiée, la liaison manque ou l''accès n''a pas été obtenu.', 1.0, NULL);
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('M3', 'medical', 'Dépenses de santé par pays (part du PIB et par habitant)', 'oms_ghed', 'hard', 'annuelle', 'pourcentage du PIB', 'certifie', 19, '2026-08-06 09:02:40.226196+00', 'Dépenses de santé par pays, en part du PIB et par habitant : le financement qui conditionne la demande medtech, à décalage long. Dix points annuels sur la Suisse depuis le run 213 (02.09.2026), après correction du filtre de période de la liaison.', 1, 'retarde', 'CHE', true, 'ÉTAT AU 24.08.2026, corrigé le 02.09 : un seul point au registre — non parce que la source n''en publie qu''un, mais parce que la liaison filtrait TimeDim ge 2023. La série GHO (GHED_CHEGDP_SHA2011) est publiée depuis 2000. Filtre passé à 2014 le 02.09.2026 (A8) ; la profondeur se constate à la collecte suivante, pas dans cette note.
INSERT INTO public.indicators (indicator_id, sector_code, label, source_id, category, frequency, unit, status, alert_threshold_pct, created_at, description_metier, sens_favorable, latence, geo_reference, en_vitrine, note_conception, seuil_consensus, periodes_incompletes_source) VALUES ('T4', 'transversal', 'Croissance du PIB mondial', 'fmi', 'hard', 'annuelle', 'pourcentage', 'certifie', NULL, '2026-08-06 09:02:40.226196+00', 'Croissance annuelle du PIB mondial : le rythme d''ensemble de la demande adressée aux branches industrielles. Douze points annuels 2014-2025 depuis le run 214 (02.09.2026), après correction du filtre de période et déclaration des valeurs négatives (2020 : -2,7 %). Toile de fond, sans seuil de matérialité : le glissement relatif d''un taux de croissance ne se lit pas.', 1, 'coincident', 'WORLD', true, 'ÉTAT AU 24.08.2026, corrigé le 02.09 : trois points ANNUELS (2023, 2024, 2025 — la fréquence « semestrielle » déclarée jusqu''au 02.09 était celle des parutions du WEO, pas de la série), valeur inchangée à 3,4 %. Trois points non parce que le FMI n''en publie que trois, mais parce que le mappage bornait la lecture à 2023 ; borne passée à 2014 le 02.09.2026 (A8), la profondeur se constate à la collecte suivante. Borné à 2025 : les années 2026+ sont des projections, écartées. N''est jamais entré dans le score (seuil de huit points) et n''a jamais rien signalé. Conservé comme toile de fond documentaire.
