INSERT INTO public.source_bindings (binding_id, indicator_id, connecteur, url_base, params, mapping, geo_defaut, statut, verifie_par, verifie_le, note) VALUES (61, 'S7', 'json_generique', 'https://api.ted.europa.eu/v3/notices/search', '{"_corps": {"limit": 1, "query": "classification-cpv IN (34700000) AND publication-date >= {{MOIS_DEBUT:1}} AND publication-date < {{MOIS_FIN:1}}", "fields": ["publication-number"]}, "_methode": "POST"}', '{"periode_fixe": "{{PERIODE:1}}", "champ_scalaire": "totalNoticeCount"}', 'EU', 'actif', 'N. Castillo', '2026-08-24 19:13:52.911255+00', 'Porté au collecteur le 25.08.2026 — mois glissant −1. Même méthode que M7, certifiée le 20.08.2026 sur le CPV 33. Remplace collecte_comptages.py, supprimé.');
