INSERT INTO public.source_bindings (binding_id, indicator_id, connecteur, url_base, params, mapping, geo_defaut, statut, verifie_par, verifie_le, note) VALUES (12, 'T2', 'csv_generique', 'https://data.snb.ch/api/cube/devkum/data/csv/fr', '{"dimSel": "D0(M0),D1(USD1,EUR1)", "fromDate": "2023-01"}', '{"filtres": {"D0": ["M0"]}, "geo_depuis": {"D1": {"EUR1": "CHF_EUR", "USD1": "CHF_USD"}}, "separateur": ";", "sauter_lignes": 3, "colonne_valeur": "Value", "colonne_periode": "Date"}', 'WORLD', 'actif', 'N. Castillo', '2026-08-09 00:00:00+00', 'BNS cube devkum, moyennes mensuelles (D0=M0). Deux séries distinguées par la zone via geo_depuis sur D1 : CHF_USD, CHF_EUR. En-tête en ligne 4 (3 lignes de métadonnées BNS + ligne vide), séparateur point-virgule, BOM. Vérifié le 09.08.2026 : 86 observations sur 2023-01..2026-07, URL testée sous forme encodée par le connecteur.');
INSERT INTO public.source_bindings (binding_id, indicator_id, connecteur, url_base, params, mapping, geo_defaut, statut, verifie_par, verifie_le, note) VALUES (1, 'A5', 'eurostat_jsonstat', 'https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/sts_inpr_m', '{"geo": "EU27_2020", "lang": "FR", "unit": "I21", "s_adj": "SCA", "format": "JSON", "nace_r2": "C29", "sinceTimePeriod": "2014-01"}', '{}', 'EU27_2020', 'actif', 'N. Castillo', '2026-08-07 00:00:00+00', 'Libellés retournés par l''API : C29 = fabrication de véhicules automobiles, remorques et semi-remorques ; I21 = indice base 2021 ; SCA = désaisonnalisé et corrigé des jours ouvrables. Les deux dernières observations portent le drapeau « i » = valeur imputée par Eurostat. · Fenêtre portée de 2023-01 à 2014-01 le 24.08.2026 (§ 5.6 : estimer une tendance avant de la retirer).');
INSERT INTO public.source_bindings (binding_id, indicator_id, connecteur, url_base, params, mapping, geo_defaut, statut, verifie_par, verifie_le, note) VALUES (3, 'S3', 'owid_csv', 'https://ourworldindata.org/grapher/yearly-number-of-objects-launched-into-outer-space.csv', '{"v": "1", "csvType": "full", "useColumnShortNames": "true"}', '{"periode_min": "2010", "colonne_code": "code", "colonne_entite": "entity", "colonne_valeur": "annual_launches", "colonne_periode": "year", "entites_retenues": ["World", "United States", "China", "Russia", "United Kingdom", "France", "Germany", "Japan", "India"]}', 'WORLD', 'actif', 'N. Castillo', '2026-08-07 00:00:00+00', 'Structure vérifiée le 07.08.2026 : colonnes entity, code, year, annual_launches. L''entité « World » porte le code OWID_WRL. Série annuelle disponible jusqu''à 2025 inclus. | Plancher de lecture abaissé de 2023 à 2010 le 24.08.2026 : la source contenait déjà ces années, le mapping les écartait. Objectif — franchir le seuil de huit points de v_sante_secteur.');
INSERT INTO public.source_bindings (binding_id, indicator_id, connecteur, url_base, params, mapping, geo_defaut, statut, verifie_par, verifie_le, note) VALUES (2, 'M2', 'eurostat_jsonstat', 'https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/sts_inpr_m', '{"geo": "EU27_2020", "lang": "FR", "unit": "I21", "s_adj": "SCA", "format": "JSON", "nace_r2": "C325", "sinceTimePeriod": "2014-01"}', '{}', 'EU27_2020', 'actif', 'N. Castillo', '2026-08-10 08:59:17.527498+00', 'Eurostat sts_inpr_m, NACE C325 (= C32.5 du § 8.4.2 : instruments et fournitures à usage médical et dentaire). Granularité spécifiée confirmée présente le 09.08.2026 : 41 valeurs mensuelles 2023-01..2026-06 (le code est C325, non C32_5). La réserve antérieure — agrégat C32 trop large, englobant bijouterie, instruments de musique, sport et jouets — est levée. Fréquence mensuelle. Reste a_verifier : à activer après vérification de la réponse réelle par l''étudiant. | Requalifié le 10.08.2026 : C32_5 vérifié inexistant dans sts_inpr_m (dimension nace_r2 à zéro membre). Collecte sur l''agrégat C32, limite de granularité énoncée au § 8.4.2. · Fenêtre portée de 2023-01 à 2014-01 le 24.08.2026 (§ 5.6 : estimer une tendance avant de la retirer).');
INSERT INTO public.source_bindings (binding_id, indicator_id, connecteur, url_base, params, mapping, geo_defaut, statut, verifie_par, verifie_le, note) VALUES (67, 'S7', 'json_generique', 'https://api.ted.europa.eu/v3/notices/search', '{"_corps": {"limit": 1, "query": "classification-cpv IN (34700000) AND publication-date >= {{MOIS_DEBUT:7}} AND publication-date < {{MOIS_FIN:7}}", "fields": ["publication-number"]}, "_methode": "POST"}', '{"periode_fixe": "{{PERIODE:7}}", "champ_scalaire": "totalNoticeCount"}', 'EU', 'actif', 'N. Castillo', '2026-08-24 19:13:52.911255+00', 'Porté au collecteur le 25.08.2026 — mois glissant −7. Même méthode que M7, certifiée le 20.08.2026 sur le CPV 33. Remplace collecte_comptages.py, supprimé.');
