INSERT INTO public.source_bindings (binding_id, indicator_id, connecteur, url_base, params, mapping, geo_defaut, statut, verifie_par, verifie_le, note) VALUES (16, 'M1', 'json_generique', 'https://comtradeapi.un.org/data/v1/get/C/A/HS', '{"period": "{{ANNEES_LISTE:12}}", "cmdCode": "9018,9019,9020,9021,9022", "flowCode": "X", "includeDesc": "true", "partnerCode": "0", "reporterCode": "276,842,156,392,528,372,484,757", "breakdownMode": "classic"}', '{"agreger": "somme", "colonne_geo": "reporterISO", "chemin_donnees": "data", "colonne_valeur": "primaryValue", "colonne_periode": "period"}', 'WORLD', 'actif', 'N. Castillo', '2026-08-09 23:14:26.8472+00', 'Allemagne, USA, Chine, Japon, Pays-Bas, Irlande, Mexique, Suisse — les principaux exportateurs d''instruments médicaux. POINT À TRANCHER AVANT ACTIVATION : la requête porte cinq positions SH. La réponse renvoie-t-elle une ligne par position ou un agrégat ? Si elle est ventilée, plusieurs valeurs coexisteront pour une même période et une même zone — il faudra soit sommer explicitement, soit redéfinir M1 sur une position unique. Décision d''agrégation à prendre et à écrire, non à subir. | Bornes rendues glissantes le 23.08.2026 : « 2023,2024,2025 » remplacé par {{ANNEES_LISTE:4}}. À revoir en réponse réelle avant réactivation. | Fenêtre portée de 4 à 12 années le 24.08.2026 (limite de périodes par requête de l''API Comtrade). Objectif — franchir le seuil de huit points.');
INSERT INTO public.source_bindings (binding_id, indicator_id, connecteur, url_base, params, mapping, geo_defaut, statut, verifie_par, verifie_le, note) VALUES (72, 'S7', 'json_generique', 'https://api.ted.europa.eu/v3/notices/search', '{"_corps": {"limit": 1, "query": "classification-cpv IN (34700000) AND publication-date >= {{MOIS_DEBUT:12}} AND publication-date < {{MOIS_FIN:12}}", "fields": ["publication-number"]}, "_methode": "POST"}', '{"periode_fixe": "{{PERIODE:12}}", "champ_scalaire": "totalNoticeCount"}', 'EU', 'actif', 'N. Castillo', '2026-08-24 19:13:52.911255+00', 'Porté au collecteur le 25.08.2026 — mois glissant −12. Même méthode que M7, certifiée le 20.08.2026 sur le CPV 33. Remplace collecte_comptages.py, supprimé.');
INSERT INTO public.source_bindings (binding_id, indicator_id, connecteur, url_base, params, mapping, geo_defaut, statut, verifie_par, verifie_le, note) VALUES (73, 'M8', 'json_generique', 'https://api.fda.gov/device/510k.json?search=decision_date:[{{MOIS_DEBUT:1}}+TO+{{MOIS_FIN_INCLUSIF:1}}]&count=decision_date', '{"_methode": "GET"}', '{"somme_champ": "count", "periode_fixe": "{{PERIODE:1}}", "chemin_donnees": "results"}', 'US', 'actif', 'N. Castillo', '2026-08-24 19:13:52.911255+00', 'Porté au collecteur le 25.08.2026 — mois glissant −1. L''URL porte les bornes en clair parce que le signe + de « +TO+ » ne doit pas être encodé : les jetons sont donc résolus dans l''URL de base, extension écrite le même jour. La réponse liste un comptage par jour ; la valeur mensuelle est leur somme, calculée par le décodeur. Remplace collecte_comptages.py, supprimé.');
