INSERT INTO public.source_bindings (binding_id, indicator_id, connecteur, url_base, params, mapping, geo_defaut, statut, verifie_par, verifie_le, note) VALUES (19, 'T1', 'csv_generique', 'https://sdmx.oecd.org/public/rest/data/OECD.SDD.STES,DSD_STES@DF_CLI/G20.M.LI...AA...H', '{"format": "csvfilewithlabels", "startPeriod": "2023-01"}', '{"colonne_code": "REF_AREA", "colonne_valeur": "OBS_VALUE", "colonne_periode": "TIME_PERIOD"}', 'G20', 'actif', 'N. Castillo', '2026-08-10 09:36:50.725026+00', 'Clé à neuf dimensions relevée dans les données du 10.08.2026, volume vérifié : 42 observations, 2023-01 à 2026-06. CSV à virgules, en-tête en première ligne. La colonne OBS_STATUS porte un statut de qualité par observation — perdu à l''ingestion, troisième occurrence du motif (Eurostat, Comtrade, OCDE).');
INSERT INTO public.source_bindings (binding_id, indicator_id, connecteur, url_base, params, mapping, geo_defaut, statut, verifie_par, verifie_le, note) VALUES (20, 'H1', 'json_generique', 'https://comtradeapi.un.org/data/v1/get/C/M/HS', '{"period": "202301,202302,202303,202304,202305,202306,202307,202308,202309,202310,202311,202312", "cmdCode": "91", "flowCode": "X", "includeDesc": "true", "reporterCode": "757", "breakdownMode": "classic"}', '{"colonne_geo": "partnerISO", "chemin_donnees": "data", "colonne_valeur": "primaryValue", "format_periode": "AAAAMM", "colonne_periode": "period"}', 'W00', 'actif', 'N. Castillo', '2026-08-10 00:00:00+00', 'Fenêtre H1 passée en partenaires exhaustifs le 21.08.2026 (retrait du filtre partnerCode — panier fixe devenu résultat calculé). Endpoint à clé requis : le point d''accès public plafonne à 500 lignes, constaté le 21.08. Auto-cohérence somme partenaires ≈ W00 à contrôler au premier run.');
