INSERT INTO public.source_bindings (binding_id, indicator_id, connecteur, url_base, params, mapping, geo_defaut, statut, verifie_par, verifie_le, note) VALUES (25, 'M3', 'json_generique', 'https://ghoapi.azureedge.net/api/GHED_CHEGDP_SHA2011', '{"$filter": "TimeDim ge 2014"}', '{"colonne_geo": "SpatialDim", "periode_min": "2014", "geo_renommage": {"GLOBAL": "WORLD"}, "chemin_donnees": "value", "colonne_valeur": "NumericValue", "colonne_periode": "TimeDim"}', 'WORLD', 'actif', 'N. Castillo', '2026-08-17 00:00:00+00', 'Mapping corrigé le 17.08.2026 après l''incident du run 33 (colonne_code au lieu de colonne_geo : ~190 pays écrasés en une ligne WORLD fausse, conservée à l''historique — registre en ajout seul). SpatialDim en ISO3, agrégats régionaux GHO (AFR, EUR…) conservés tels quels et à tenir hors classements ; GLOBAL renommé WORLD via geo_renommage pour superseder le dernier point WORLD. Réponse réelle vue le 17.08.2026. · 02.09.2026 (A8) : filtre TimeDim ge 2023 → ge 2014 ; le point unique au registre était l''effet de ce filtre, pas une limite de la source (GHO publie depuis 2000).');
INSERT INTO public.source_bindings (binding_id, indicator_id, connecteur, url_base, params, mapping, geo_defaut, statut, verifie_par, verifie_le, note) VALUES (24, 'A3', 'csv_generique', 'https://api.iea.org/evs', '{"csv": "true", "mode": "Cars", "year": "2023", "category": "Historical", "parameters": "EV sales"}', '{"filtres": {"unit": ["Vehicles"], "parameter": ["EV sales"], "powertrain": ["EV"]}, "colonne_code": "region", "colonne_valeur": "value", "colonne_periode": "year"}', 'WORLD', 'actif', 'N. Castillo', '2026-08-17 00:00:00+00', 'Réponse réelle vue le 17.08.2026 : CSV region,category,parameter,mode,powertrain,year,unit,value ; year obligatoire ; granularité pays confirmée, agrégats mêlés aux pays (à exclure des classements côté page). Filtres : EV sales / EV / Vehicles.');
INSERT INTO public.source_bindings (binding_id, indicator_id, connecteur, url_base, params, mapping, geo_defaut, statut, verifie_par, verifie_le, note) VALUES (27, 'A3', 'csv_generique', 'https://api.iea.org/evs', '{"csv": "true", "mode": "Cars", "year": "2024", "category": "Historical", "parameters": "EV sales"}', '{"filtres": {"unit": ["Vehicles"], "parameter": ["EV sales"], "powertrain": ["EV"]}, "colonne_code": "region", "colonne_valeur": "value", "colonne_periode": "year"}', 'WORLD', 'actif', 'N. Castillo', '2026-08-17 00:00:00+00', 'Liaison sœur de la fenêtre 2023 (motif H1, une liaison par année). Réponse réelle de cette année À VOIR avant activation.');
INSERT INTO public.source_bindings (binding_id, indicator_id, connecteur, url_base, params, mapping, geo_defaut, statut, verifie_par, verifie_le, note) VALUES (21, 'H1', 'json_generique', 'https://comtradeapi.un.org/data/v1/get/C/M/HS', '{"period": "202401,202402,202403,202404,202405,202406,202407,202408,202409,202410,202411,202412", "cmdCode": "91", "flowCode": "X", "includeDesc": "true", "reporterCode": "757", "breakdownMode": "classic"}', '{"colonne_geo": "partnerISO", "chemin_donnees": "data", "colonne_valeur": "primaryValue", "format_periode": "AAAAMM", "colonne_periode": "period"}', 'W00', 'actif', 'N. Castillo', '2026-08-10 00:00:00+00', 'Fenêtre H1 passée en partenaires exhaustifs le 21.08.2026 (retrait du filtre partnerCode — panier fixe devenu résultat calculé). Endpoint à clé requis : le point d''accès public plafonne à 500 lignes, constaté le 21.08. Auto-cohérence somme partenaires ≈ W00 à contrôler au premier run.');
INSERT INTO public.source_bindings (binding_id, indicator_id, connecteur, url_base, params, mapping, geo_defaut, statut, verifie_par, verifie_le, note) VALUES (79, 'M8', 'json_generique', 'https://api.fda.gov/device/510k.json?search=decision_date:[{{MOIS_DEBUT:7}}+TO+{{MOIS_FIN_INCLUSIF:7}}]&count=decision_date', '{"_methode": "GET"}', '{"somme_champ": "count", "periode_fixe": "{{PERIODE:7}}", "chemin_donnees": "results"}', 'US', 'actif', 'N. Castillo', '2026-08-24 19:13:52.911255+00', 'Porté au collecteur le 25.08.2026 — mois glissant −7. L''URL porte les bornes en clair parce que le signe + de « +TO+ » ne doit pas être encodé : les jetons sont donc résolus dans l''URL de base, extension écrite le même jour. La réponse liste un comptage par jour ; la valeur mensuelle est leur somme, calculée par le décodeur. Remplace collecte_comptages.py, supprimé.');
