INSERT INTO public.source_bindings (binding_id, indicator_id, connecteur, url_base, params, mapping, geo_defaut, statut, verifie_par, verifie_le, note) VALUES (34, 'T3', 'xlsx_indexe', 'https://www.cpb.nl/en/worldtrademonitor/latest', '{}', '{"plage": "B4:MZ60", "feuille": "trade_out", "motif_lien": "href=\"([^\"]*[Ww]orld[_ -]?[Tt]rade[_ -]?[Mm]onitor[^\"]*\\.xlsx)\"", "entites_geo": {"tgz_w1_qnmi_sn": "WORLD"}, "periode_min": "2023", "motif_periode": "^\\d{4}[Mm]\\d{2}$", "colonne_entite": "__EMPTY", "entites_retenues": ["tgz_w1_qnmi_sn"]}', 'WORLD', 'actif', 'N. Castillo', '2026-08-17 00:00:00+00', 'Classeur réel inspecté le 17.08.2026 (openpyxl, annexe 5) : feuille trade_out, périodes en ligne 4 dès la colonne F (2000m01), série cible par code stable tgz_w1_qnmi_sn (World trade, volume dsa, 2021=100), libellés voisins d''un horodatage variable. Page morte remplacée par /latest (lien xlsx présent en HTML statique, résolution automatique). Clé __EMPTY pour la colonne de codes : hypothèse SheetJS, à confronter au premier run.');
INSERT INTO public.source_bindings (binding_id, indicator_id, connecteur, url_base, params, mapping, geo_defaut, statut, verifie_par, verifie_le, note) VALUES (33, 'S4', 'xlsx_indexe', 'https://www.sipri.org/databases/milex', '{}', '{"plage": "A6:CA400", "feuille": "Current US$", "motif_lien": "href=\"([^\"]*SIPRI-Milex-data[^\"]*\\.xlsx)\"", "entites_geo": {"China": "CHN", "India": "IND", "Japan": "JPN", "France": "FRA", "Russia": "RUS", "Germany": "DEU", "Switzerland": "CHE", "Korea, South": "KOR", "Saudi Arabia": "SAU", "United Kingdom": "GBR", "United States of America": "USA"}, "periode_min": "2010", "motif_periode": "^\\d{4}$", "colonne_entite": "Country", "entites_retenues": ["United States of America", "China", "Russia", "India", "Saudi Arabia", "United Kingdom", "Germany", "France", "Japan", "Korea, South", "Switzerland"]}', 'WORLD', 'actif', 'N. Castillo', '2026-08-17 00:00:00+00', 'Classeur réel inspecté le 17.08.2026 (openpyxl, sortie en annexe 5) : feuille Current US$, en-tête ligne 6 (Country, Notes, 1949..2025), libellés du panier confirmés pour USA/CHN/KOR/RUS/CHE/SAU, série jusqu''à 2025, unité millions USD. Drapeaux de qualité portés par la couleur des cellules — perdus par construction, consigné pour le § 12.5. | Plancher de lecture abaissé de 2023 à 2010 le 24.08.2026 : la source contenait déjà ces années, le mapping les écartait. Objectif — franchir le seuil de huit points de v_sante_secteur.');
INSERT INTO public.source_bindings (binding_id, indicator_id, connecteur, url_base, params, mapping, geo_defaut, statut, verifie_par, verifie_le, note) VALUES (35, 'T5', 'eurostat_jsonstat', 'https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/ei_bsin_m_r2', '{"geo": "EU27_2020", "lang": "en", "unit": "BAL", "indic": "BS-IPE", "s_adj": "SA", "format": "JSON", "sinceTimePeriod": "2014-01"}', '{"admet_negatifs": true}', 'EU27_2020', 'actif', 'N. Castillo', '2026-08-17 00:00:00+00', 'Structure du jeu vérifiée le 17.08.2026 (dimensions freq/indic/s_adj/unit/geo/time ; code BS-IPE présent). La réponse FILTRÉE de cette liaison reste à voir avant activation — commande en fin de migration. · Fenêtre portée de 2023-01 à 2014-01 le 24.08.2026 (§ 5.6 : estimer une tendance avant de la retirer).');
INSERT INTO public.source_bindings (binding_id, indicator_id, connecteur, url_base, params, mapping, geo_defaut, statut, verifie_par, verifie_le, note) VALUES (36, 'T6', 'csv_generique', 'https://tsdb-api.kof.ethz.ch/v2/ts', '{"keys": "ch.kof.barometer", "mime": "csv", "access_type": "public"}', '{"periode_min": "2023", "colonne_valeur": "ch.kof.barometer", "format_periode": "AAAA-MM-JJ", "colonne_periode": "date"}', 'CH', 'actif', 'N. Castillo', '2026-08-17 00:00:00+00', 'CSV vu en réponse réelle le 17.08.2026 (colonnes date / ch.kof.barometer, dates au premier du mois — d''où format_periode AAAA-MM-JJ, normalisation ajoutée au décodeur CSV le même jour). REQUIERT le réimport du collecteur générique.');
