INSERT INTO public.source_bindings (binding_id, indicator_id, connecteur, url_base, params, mapping, geo_defaut, statut, verifie_par, verifie_le, note) VALUES (29, 'H2', 'eurostat_jsonstat', 'https://www.pxweb.bfs.admin.ch/api/v1/fr/px-x-0602010000_103/px-x-0602010000_103.px', '{"_corps": {"query": [{"code": "Jahr", "selection": {"filter": "item", "values": ["2023"]}}, {"code": "Kanton", "selection": {"filter": "item", "values": ["999"]}}, {"code": "Wirtschaftsart", "selection": {"filter": "item", "values": ["265201", "265202", "265203", "265204", "265205"]}}, {"code": "Beobachtungseinheit", "selection": {"filter": "item", "values": ["2"]}}], "response": {"format": "json-stat2"}}, "_methode": "POST"}', '{"agreger": "somme", "dim_temps": "Jahr"}', 'CH', 'suspendu', 'N. Castillo', '2026-08-17 00:00:00+00', 'OFS STATENT, table px-x-0602010000_103, POST JSON-stat2. Métadonnées vues en réponse réelle le 17.08.2026 ; la réponse POST elle-même reste À VOIR avant activation. Emplois (Beobachtungseinheit=2), Suisse (Kanton 999), 5 classes NOGA 2652 sommées (motif M1). Série arrêtée à 2023 — limite de fraîcheur STATENT. Fenêtre réduite à 2023 le 17.08.2026 (alignement sur FENETRE_DEBUT des contrôles qualité — les millésimes 2021/2022 étaient systématiquement écartés). — DÉSACTIVÉE le 25.08.2026 : fenêtre littérale figée sur 2023, remplacée par la liaison glissante (filtre PX-Web top: 4).');
INSERT INTO public.source_bindings (binding_id, indicator_id, connecteur, url_base, params, mapping, geo_defaut, statut, verifie_par, verifie_le, note) VALUES (30, 'M4', 'eurostat_jsonstat', 'https://www.pxweb.bfs.admin.ch/api/v1/fr/px-x-0602010000_103/px-x-0602010000_103.px', '{"_corps": {"query": [{"code": "Jahr", "selection": {"filter": "item", "values": ["2023"]}}, {"code": "Kanton", "selection": {"filter": "item", "values": ["999"]}}, {"code": "Wirtschaftsart", "selection": {"filter": "item", "values": ["266000", "325001", "325002", "325003", "325004"]}}, {"code": "Beobachtungseinheit", "selection": {"filter": "item", "values": ["2"]}}], "response": {"format": "json-stat2"}}, "_methode": "POST"}', '{"agreger": "somme", "dim_temps": "Jahr"}', 'CH', 'suspendu', 'N. Castillo', '2026-08-17 00:00:00+00', 'OFS STATENT, même table et même transport que H2. Emplois (Beobachtungseinheit=2), Suisse (999), classes 266000 + 325001-325004 sommées — périmètre qualifié au § 8.4.2 (NOGA 32.5 et 26.6). Réponse POST À VOIR avant activation. Série arrêtée à 2023. Fenêtre réduite à 2023 le 17.08.2026 (alignement sur FENETRE_DEBUT des contrôles qualité — les millésimes 2021/2022 étaient systématiquement écartés). — DÉSACTIVÉE le 25.08.2026 : fenêtre littérale figée sur 2023, remplacée par la liaison glissante (filtre PX-Web top: 4).');
INSERT INTO public.source_bindings (binding_id, indicator_id, connecteur, url_base, params, mapping, geo_defaut, statut, verifie_par, verifie_le, note) VALUES (99, 'A8', 'json_generique', 'https://api.ted.europa.eu/v3/notices/search', '{"_corps": {"limit": 1, "query": "classification-cpv IN (34310000, 34312000, 34320000) AND publication-date >= {{MOIS_DEBUT:1}} AND publication-date < {{MOIS_FIN:1}}", "fields": ["publication-number"]}, "_methode": "POST"}', '{"periode_fixe": "{{PERIODE:1}}", "champ_scalaire": "totalNoticeCount"}', 'EU', 'a_verifier', NULL, NULL, 'Comptage mensuel des avis TED en pièces mécaniques automobiles, mois révolu n-1. Patron de M7, qualifié le 20.08.2026. CPV repris du flux ted_automobile_v2, affinés le 23.08 après analyse de 250 avis. Reconnaissance du 25.08.2026 : 91 avis en 2026-07, 89 en 2026-06, 90 en 2026-05.');
