INSERT INTO public.source_bindings (binding_id, indicator_id, connecteur, url_base, params, mapping, geo_defaut, statut, verifie_par, verifie_le, note) VALUES (85, 'M7', 'json_generique', 'https://api.ted.europa.eu/v3/notices/search', '{"_corps": {"limit": 1, "query": "classification-cpv IN (33100000) AND publication-date >= {{MOIS_DEBUT:1}} AND publication-date < {{MOIS_FIN:1}}", "fields": ["publication-number"]}, "_methode": "POST"}', '{"periode_fixe": "{{PERIODE:1}}", "champ_scalaire": "totalNoticeCount"}', 'EU', 'actif', 'N. Castillo', '2026-08-24 19:19:13.551583+00', 'Mois glissant −1. Méthode certifiée le 20.08.2026 et vérifiée en réponse réelle — sept mois de données au registre. RÉACTIVÉE le 25.08.2026 : les liaisons étaient restées au statut a_verifier depuis leur création, donc invisibles du collecteur ; l''indicateur ne collectait plus depuis le run 78 sans qu''aucun signal ne le dise. Fenêtre portée de sept à douze mois, alignée sur S7.');
