INSERT INTO public.source_bindings (binding_id, indicator_id, connecteur, url_base, params, mapping, geo_defaut, statut, verifie_par, verifie_le, note) VALUES (17, 'A4', 'json_generique', 'https://comtradeapi.un.org/data/v1/get/C/A/HS', '{"period": "{{ANNEES_LISTE:12}}", "cmdCode": "8708", "flowCode": "X", "includeDesc": "true", "partnerCode": "0", "reporterCode": "276,156,842,392,484,410,203,616", "breakdownMode": "classic"}', '{"colonne_geo": "reporterISO", "chemin_donnees": "data", "colonne_valeur": "primaryValue", "colonne_periode": "period"}', 'WORLD', 'actif', 'N. Castillo', '2026-08-09 23:14:26.8472+00', 'Allemagne, Chine, USA, Japon, Mexique, Corée du Sud, Tchéquie, Pologne — les pays où se concentre la production de pièces automobiles. Panier volontairement large : c''est l''indicateur qui mesure le marché directement adressable par la sous-traitance de précision. | Bornes rendues glissantes le 23.08.2026 (complément) : « 2023,2024,2025 » remplacé par {{ANNEES_LISTE:4}}. Manqué par la détection initiale, rattrapé par le contrôle V41. À revoir en réponse réelle avant réactivation. | Fenêtre portée de 4 à 12 années le 24.08.2026 (limite de périodes par requête de l''API Comtrade). Objectif — franchir le seuil de huit points.');
