INSERT INTO public.source_bindings (binding_id, indicator_id, connecteur, url_base, params, mapping, geo_defaut, statut, verifie_par, verifie_le, note) VALUES (47, 'A6', 'eurostat_jsonstat', 'https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/sts_inpr_m', '{"geo": "EU27_2020", "lang": "FR", "unit": "I21", "s_adj": "SCA", "format": "JSON", "nace_r2": "C293", "sinceTimePeriod": "2014-01"}', '{}', 'EU27_2020', 'actif', 'N. Castillo', '2026-08-24 13:43:11.975625+00', 'Vu en réponse réelle le 24.08.2026 : 150 points, 2014-01 à 2026-06, dernier 91,6. À lire en regard de A5 (C29 = 106,6 à la même date) : quinze points d''écart entre le marché final et la demande adressable.');
