INSERT INTO public.source_bindings (binding_id, indicator_id, connecteur, url_base, params, mapping, geo_defaut, statut, verifie_par, verifie_le, note) VALUES (49, 'S8', 'eurostat_jsonstat', 'https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/sts_inpr_m', '{"geo": "EU27_2020", "lang": "FR", "unit": "I21", "s_adj": "SCA", "format": "JSON", "nace_r2": "C303", "sinceTimePeriod": "2014-01"}', '{}', 'EU27_2020', 'actif', 'N. Castillo', '2026-08-24 13:43:11.975625+00', 'Vu en réponse réelle le 24.08.2026 : 150 points, 2014-01 à 2026-06, dernier 150,8 — la branche produit cinquante pour cent au-dessus de sa base 2021.');
INSERT INTO public.source_bindings (binding_id, indicator_id, connecteur, url_base, params, mapping, geo_defaut, statut, verifie_par, verifie_le, note) VALUES (50, 'T11', 'eurostat_jsonstat', 'https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/sts_inpr_m', '{"geo": "CH", "lang": "FR", "unit": "I21", "s_adj": "SCA", "format": "JSON", "nace_r2": "C", "sinceTimePeriod": "2014-01"}', '{}', 'CH', 'actif', 'N. Castillo', '2026-08-24 13:43:11.975625+00', 'Vu en réponse réelle le 24.08.2026 : 150 points, dernier 124,7. LIMITE CONSTATÉE ET DÉCLARÉE : la ventilation par branche NACE n''existe pas pour la Suisse dans cette source — C25, C256 et C2562 y sont vides, seul l''agrégat manufacturier répond.');
INSERT INTO public.source_bindings (binding_id, indicator_id, connecteur, url_base, params, mapping, geo_defaut, statut, verifie_par, verifie_le, note) VALUES (51, 'T8', 'eurostat_jsonstat', 'https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/ei_bsin_m_r2', '{"geo": "EU27_2020", "lang": "FR", "indic": "BS-IOB", "s_adj": "SA", "format": "JSON", "sinceTimePeriod": "2014-01"}', '{"admet_negatifs": true}', 'EU27_2020', 'actif', 'N. Castillo', '2026-08-24 13:43:11.975625+00', 'Vu en réponse réelle le 24.08.2026 : 151 points, 2014-01 à 2026-07, dernier -17,5 (carnets jugés inférieurs à la normale, en amélioration depuis -19,9 en février). Solde d''opinion : grandeur intensive et négative, drapeau admet_negatifs posé.');
