INSERT INTO public.source_bindings (binding_id, indicator_id, connecteur, url_base, params, mapping, geo_defaut, statut, verifie_par, verifie_le, note) VALUES (53, 'T10', 'eurostat_jsonstat', 'https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/ei_bsin_q_r2', '{"geo": "EU27_2020", "lang": "FR", "indic": "BS-FLP2-PC", "s_adj": "NSA", "format": "JSON", "sinceTimePeriod": "2014-Q1"}', '{"admet_negatifs": true}', 'EU27_2020', 'actif', 'N. Castillo', '2026-08-24 13:43:11.975625+00', 'Vu en réponse réelle le 24.08.2026 : 51 points trimestriels, dernier 33,5 % — en baisse depuis 37 %, donc signal favorable puisque le sens est inversé.');
