INSERT INTO public.source_bindings (binding_id, indicator_id, connecteur, url_base, params, mapping, geo_defaut, statut, verifie_par, verifie_le, note) VALUES (28, 'A3', 'csv_generique', 'https://api.iea.org/evs', '{"csv": "true", "mode": "Cars", "year": "{{ANNEE_MOINS:1}}", "category": "Historical", "parameters": "EV sales"}', '{"filtres": {"unit": ["Vehicles"], "parameter": ["EV sales"], "powertrain": ["EV"]}, "colonne_code": "region", "colonne_valeur": "value", "colonne_periode": "year"}', 'WORLD', 'actif', 'N. Castillo (délégation du 25.08.2026)', '2026-08-25 00:00:00+00', 'Liaison sœur de la fenêtre 2023 (motif H1, une liaison par année). Réponse réelle de cette année À VOIR avant activation. | Bornes rendues glissantes le 23.08.2026 : année 2025 remplacée par {{ANNEE_COURANTE}}. À revoir en réponse réelle avant réactivation.');
INSERT INTO public.source_bindings (binding_id, indicator_id, connecteur, url_base, params, mapping, geo_defaut, statut, verifie_par, verifie_le, note) VALUES (57, 'M6', 'csv_generique', 'https://sdmx.oecd.org/public/rest/data/OECD.STI.PIE,DSD_PATENTS@DF_PATENTS_OECDSPECIFIC,1.0/6F0.A.AP.PATN.PRIORITY.CHE+DEU+USA+CHN+JPN+FRA..APPLICANT...MEDICAL', '{"format": "csvfilewithlabels", "startPeriod": "2010"}', '{"periode_min": "2010", "colonne_code": "REF_AREA", "colonne_valeur": "OBS_VALUE", "colonne_periode": "TIME_PERIOD"}', 'CHE', 'actif', 'N. Castillo', '2026-08-24 15:52:54.712996+00', 'Vu en réponse réelle le 25.08.2026 : 78 lignes, 13 périodes 2010-2022, six zones. Dernier point CHE 689,4 — la valeur est fractionnaire parce que l''OCDE attribue les brevets co-déposés au prorata des déposants, ce qui est la convention du producteur et non un artefact. · CORRECTIF 25.08.2026 : la clé portait douze segments au lieu de onze — un point de trop après la liste de zones. Le service répondait 404, et le collecteur l''a consigné comme tel.');
INSERT INTO public.source_bindings (binding_id, indicator_id, connecteur, url_base, params, mapping, geo_defaut, statut, verifie_par, verifie_le, note) VALUES (54, 'H7', 'pdf_tabulaire_indexe', 'https://www.fhs.swiss/fre/statistics.html', '{"format": "PDF", "langue": "f", "document": "histo_elec-meca"}', '{"colonne": "total_chf", "extraction": "nœud de lecture PDF, analyse en flux de jetons", "lien_depuis_index": "/scripts/getstat.php?file=histo_elec-meca_<millesime>_f.pdf"}', 'CH', 'actif', 'N. Castillo', '2026-08-24 14:39:23.570068+00', 'Vu en réponse réelle le 24.08.2026, reconfirmé le 25.08 : 19 lignes mensuelles, 2025-01 à 2026-07. Contrôle de cohérence AVANT écriture — électroniques + mécaniques contre total : écart moyen 0,00 %, maximum 0,01 %, ordre des colonnes confirmé. · PORTÉ EN WORKFLOW le 25.08.2026 (collecteFhV1) : plus aucun script. Le nœud de lecture PDF de l''orchestrateur ne préserve PAS l''alignement des colonnes — vérifié en réponse réelle, un découpage par lignes ne rend que deux ou trois valeurs sur six. L''analyse se fait donc EN FLUX DE JETONS : les nombres restent dans le bon ordre, seuls les sauts de ligne sont arbitraires. Résultat identique au script remplacé. · Extraction DÉTERMINISTE et non par IA : le document contient un tableau, seule son enveloppe est non structurée — à la différence du communiqué ACEA, en prose.');
INSERT INTO public.source_bindings (binding_id, indicator_id, connecteur, url_base, params, mapping, geo_defaut, statut, verifie_par, verifie_le, note) VALUES (55, 'H8', 'pdf_tabulaire_indexe', 'https://www.fhs.swiss/fre/statistics.html', '{"format": "PDF", "langue": "f", "document": "histo_elec-meca"}', '{"colonne": "meca_chf", "extraction": "nœud de lecture PDF, analyse en flux de jetons", "lien_depuis_index": "/scripts/getstat.php?file=histo_elec-meca_<millesime>_f.pdf"}', 'CH', 'actif', 'N. Castillo', '2026-08-24 14:39:23.570068+00', 'Vu en réponse réelle le 24.08.2026, reconfirmé le 25.08 : 19 lignes mensuelles, 2025-01 à 2026-07. Contrôle de cohérence AVANT écriture — électroniques + mécaniques contre total : écart moyen 0,00 %, maximum 0,01 %, ordre des colonnes confirmé. · PORTÉ EN WORKFLOW le 25.08.2026 (collecteFhV1) : plus aucun script. Le nœud de lecture PDF de l''orchestrateur ne préserve PAS l''alignement des colonnes — vérifié en réponse réelle, un découpage par lignes ne rend que deux ou trois valeurs sur six. L''analyse se fait donc EN FLUX DE JETONS : les nombres restent dans le bon ordre, seuls les sauts de ligne sont arbitraires. Résultat identique au script remplacé. · Extraction DÉTERMINISTE et non par IA : le document contient un tableau, seule son enveloppe est non structurée — à la différence du communiqué ACEA, en prose.');
