INSERT INTO public.source_bindings (binding_id, indicator_id, connecteur, url_base, params, mapping, geo_defaut, statut, verifie_par, verifie_le, note) VALUES (97, 'H2', 'eurostat_jsonstat', 'https://www.pxweb.bfs.admin.ch/api/v1/fr/px-x-0602010000_103/px-x-0602010000_103.px', '{"_corps": {"query": [{"code": "Jahr", "selection": {"filter": "top", "values": ["4"]}}, {"code": "Kanton", "selection": {"filter": "item", "values": ["999"]}}, {"code": "Wirtschaftsart", "selection": {"filter": "item", "values": ["265201", "265202", "265203", "265204", "265205"]}}, {"code": "Beobachtungseinheit", "selection": {"filter": "item", "values": ["2"]}}], "response": {"format": "json-stat2"}}, "_methode": "POST"}', '{"agreger": "somme", "dim_temps": "Jahr"}', 'CH', 'suspendu', 'N. Castillo (délégation du 25.08.2026)', '2026-08-25 00:00:00+00', 'Fenêtre glissante par filtre PX-Web « top: 4 » — remplace la liaison 29, figée sur 2023. Reconnaissance du 25.08.2026 : HTTP 200, années 2021-2024, 20 valeurs non nulles. À activer nominativement ; désactiver la liaison 29 dans le même geste, faute de quoi 2023 serait collecté deux fois. — SUSPENDUE le 28.08.2026 au profit de la liaison pleine profondeur (top: 14), pour éviter la double collecte.');
