INSERT INTO public.source_bindings (binding_id, indicator_id, connecteur, url_base, params, mapping, geo_defaut, statut, verifie_par, verifie_le, note) VALUES (98, 'M4', 'eurostat_jsonstat', 'https://www.pxweb.bfs.admin.ch/api/v1/fr/px-x-0602010000_103/px-x-0602010000_103.px', '{"_corps": {"query": [{"code": "Jahr", "selection": {"filter": "top", "values": ["4"]}}, {"code": "Kanton", "selection": {"filter": "item", "values": ["999"]}}, {"code": "Wirtschaftsart", "selection": {"filter": "item", "values": ["266000", "325001", "325002", "325003", "325004"]}}, {"code": "Beobachtungseinheit", "selection": {"filter": "item", "values": ["2"]}}], "response": {"format": "json-stat2"}}, "_methode": "POST"}', '{"agreger": "somme", "dim_temps": "Jahr"}', 'CH', 'suspendu', 'N. Castillo (délégation du 25.08.2026)', '2026-08-25 00:00:00+00', 'Fenêtre glissante par filtre PX-Web « top: 4 » — remplace la liaison 30, figée sur 2023. Même table et même reconnaissance que H2 (25.08.2026) ; seuls les codes Wirtschaftsart diffèrent. À activer nominativement, en désactivant la liaison 30 dans le même geste. — SUSPENDUE le 28.08.2026 au profit de la liaison pleine profondeur (top: 14), pour éviter la double collecte.');
INSERT INTO public.source_bindings (binding_id, indicator_id, connecteur, url_base, params, mapping, geo_defaut, statut, verifie_par, verifie_le, note) VALUES (144, 'H12', 'eurostat_jsonstat', 'https://www.pxweb.bfs.admin.ch/api/v1/fr/px-x-0602010000_103/px-x-0602010000_103.px', '{"_corps": {"query": [{"code": "Jahr", "selection": {"filter": "top", "values": ["14"]}}, {"code": "Kanton", "selection": {"filter": "item", "values": ["999"]}}, {"code": "Wirtschaftsart", "selection": {"filter": "item", "values": ["265201", "265202", "265203", "265204", "265205"]}}, {"code": "Beobachtungseinheit", "selection": {"filter": "item", "values": ["2"]}}], "response": {"format": "json-stat2"}}, "_methode": "POST"}', '{"agreger": "somme", "dim_temps": "Jahr"}', 'CH', 'actif', 'N. Castillo (délégation du 30.08.2026)', '2026-08-30 21:09:34.766784+00', 'Reprise à l''identique de la liaison 143, transférée de H2 à H12 le 30.08.2026 — même cube STATENT, mêmes cinq classes NOGA 2652, même profondeur (top: 14). Seul l''indicateur porteur change.');
INSERT INTO public.source_bindings (binding_id, indicator_id, connecteur, url_base, params, mapping, geo_defaut, statut, verifie_par, verifie_le, note) VALUES (143, 'H2', 'eurostat_jsonstat', 'https://www.pxweb.bfs.admin.ch/api/v1/fr/px-x-0602010000_103/px-x-0602010000_103.px', '{"_corps": {"query": [{"code": "Jahr", "selection": {"filter": "top", "values": ["14"]}}, {"code": "Kanton", "selection": {"filter": "item", "values": ["999"]}}, {"code": "Wirtschaftsart", "selection": {"filter": "item", "values": ["265201", "265202", "265203", "265204", "265205"]}}, {"code": "Beobachtungseinheit", "selection": {"filter": "item", "values": ["2"]}}], "response": {"format": "json-stat2"}}, "_methode": "POST"}', '{"agreger": "somme", "dim_temps": "Jahr"}', 'CH', 'suspendu', 'N. Castillo (délégation du 28.08.2026)', '2026-08-27 22:30:31.779973+00', 'Profondeur pleine du cube STATENT (2011-2024, vérifiée sur métadonnées PX-Web le 28.08.2026) — remplace la liaison 97 (top: 4). Quatorze points : le motif d''écart de la vitrine (moins de douze points) tombe. — SUSPENDUE le 30.08.2026 : H2 est passé au recensement CP ; la collecte STATENT continue sous H12.');
INSERT INTO public.source_bindings (binding_id, indicator_id, connecteur, url_base, params, mapping, geo_defaut, statut, verifie_par, verifie_le, note) VALUES (145, 'A11', 'csv_generique', 'https://api.iea.org/evs', '{"csv": "true", "mode": "Cars", "year": "{{ANNEE_MOINS:1}}", "category": "Historical", "parameters": "EV sales share"}', '{"filtres": {"unit": ["percent"], "parameter": ["EV sales share"], "powertrain": ["EV"]}, "colonne_code": "region", "colonne_valeur": "value", "colonne_periode": "year"}', 'WORLD', 'actif', 'N. Castillo (délégation du 01.09.2026)', '2026-09-01 16:39:27.673101+00', 'Liaison perpétuelle au jeton {{ANNEE_MOINS:1}}, à l''image de la liaison 28 (A3) : l''année est résolue à l''exécution. Comble l''angle mort relevé à l''audit de fraîcheur du 01.09.2026.');
INSERT INTO public.source_bindings (binding_id, indicator_id, connecteur, url_base, params, mapping, geo_defaut, statut, verifie_par, verifie_le, note) VALUES (13, 'T4', 'json_generique', 'https://www.imf.org/external/datamapper/api/v1/NGDP_RPCH/WEOWORLD', '{}', '{"periode_max": "2025", "periode_min": "2014", "admet_negatifs": true, "chemin_donnees": "values.NGDP_RPCH.WEOWORLD", "objet_par_periode": true}', 'WORLD', 'actif', 'N. Castillo', '2026-08-09 00:00:00+00', 'FMI DataMapper, indicateur NGDP_RPCH (croissance PIB réel), agrégat WEOWORLD. Structure imbriquée annee->valeur, lue par le mode objet_par_periode du connecteur. Vérifié le 09.08.2026 : 2023=3.3, 2024=3.4, 2025=3.4. Borné à 2025 : les années 2026+ sont des PROJECTIONS FMI, écartées tant que leur statut (distinct de valide_source) n''est pas tranché. · 02.09.2026 (A8) : periode_min 2023 → 2014 ; les trois points au registre étaient l''effet de cette borne, pas une limite de la source. · 02.09.2026 (A8, après run 213) : admet_negatifs déclaré — 2020 (-2,7 %) écarté comme « valeur négative », 2021 écarté par ricochet (+348 % contre -2,7).');
INSERT INTO public.flux_sources (flux_id, famille, sector_code, libelle, url_base, parametres, statut, qualified_by, qualified_at, note, lecture_evenementielle) VALUES ('gdelt_horlogerie', 'actualite', 'horlogerie', 'GDELT : actualité mondiale de l''industrie horlogère', 'https://api.gdeltproject.org/api/v2/doc/doc', '{"limite": 50, "fenetre": "7d", "requete": "(\"swiss watch industry\" OR \"watch exports\" OR \"horlogerie suisse\")"}', 'actif', 'N. Castillo', '2026-08-24', 'GDELT DOC 2.0. Vue en réponse réelle le 22.08.2026, 11 articles seulement — le vocabulaire horloger est peu représenté dans le corpus de presse indexé. Retenu malgré le faible rendement : une absence mesurée vaut mieux qu''une absence supposée.', true);
INSERT INTO public.flux_sources (flux_id, famille, sector_code, libelle, url_base, parametres, statut, qualified_by, qualified_at, note, lecture_evenementielle) VALUES ('presse_spatial_spacenews', 'communications', 'aerospatial', 'SpaceNews : industrie spatiale (fil RSS)', 'https://spacenews.com/feed/', '{"_note": "Presse de référence du spatial : contrats, constellations, lanceurs, budgets. Les constellations demandent de la série là où le spatial était unitaire — l''effet sur la sous-traitance identifié au § 8.4.5. Vu en réponse réelle le 26.08.2026 : 20 items."}', 'actif', 'N. Castillo (délégation du 26.08.2026)', '2026-08-26', 'FlightGlobal et Aviation Week, vivants, ont été écartés : exploitation aérienne civile, payant au clic — loin de l''usinage.', true);
INSERT INTO public.flux_sources (flux_id, famille, sector_code, libelle, url_base, parametres, statut, qualified_by, qualified_at, note, lecture_evenementielle) VALUES ('ted_medical', 'marches_publics', 'medical', 'Avis TED : équipements et fournitures médicaux (CPV 33)', 'https://api.ted.europa.eu/v3/notices/search', '{"cpv": "33100000", "_note": " | 23.08.2026 : fenêtre portée de 7 à 30 jours (décision de l''étudiant). L''API TED est libre et le volume mensuel reste modeste ; la fenêtre courte privait la file d''examen de matière. Limite maintenue à 50 : le volume mensuel de ce CPV se compte en centaines (automobile large) ou en milliers (médical), et la file d''examen humaine ne s''inonde pas — la limite mord donc avant la fenêtre, ce qui est assumé.", "limite": 50, "cpv_statut": "verifie_20.08.2026_via_M7", "fenetre_jours": 30}', 'actif', 'N. Castillo', '2026-08-24', 'CPV 33100000 (équipements médicaux). Décompte vérifié en réponse réelle TED v3 le 23.08.2026 : 11 752 avis sur 60 jours, 250 enrichis en base. Alimente M7 (comptage mensuel) et l''écran Actions. | NON ÉLIGIBLE à la lecture événementielle (01.09.2026) : enregistrement structuré, compté par indicateur et servi dans la file d''examen ; relu comme « événement », un avis ou une autorisation devenait un faux « investissement » ou une redite.', false);
INSERT INTO public.flux_sources (flux_id, famille, sector_code, libelle, url_base, parametres, statut, qualified_by, qualified_at, note, lecture_evenementielle) VALUES ('ted_aerospatial', 'marches_publics', 'aerospatial', 'Avis TED : aéronefs, engins spatiaux et équipements associés', 'https://api.ted.europa.eu/v3/notices/search', '{"cpv": "34700000", "_note": " | 23.08.2026 : fenêtre portée de 7 à 30 jours (décision de l''étudiant). L''API TED est libre et le volume mensuel reste modeste ; la fenêtre courte privait la file d''examen de matière. Limite portée à 100 : le volume mensuel de ce CPV tient sous ce plafond, la fenêtre n''est donc pas tronquée par la limite.", "limite": 100, "cpv_statut": "a_verifier", "fenetre_jours": 30}', 'actif', 'N. Castillo', '2026-08-24', 'CPV 34700000 (aéronefs et engins spatiaux). Décompte vérifié en réponse réelle le 23.08.2026, 75 items. Alimente S7 (comptage mensuel). Réserve : la lecture décisionnelle du 24.08 n''y a trouvé aucun avis adressable — les avis relèvent d''achat d''appareils complets, de MRO et de distribution, non de sous-traitance d''usinage. | NON ÉLIGIBLE à la lecture événementielle (01.09.2026) : enregistrement structuré, compté par indicateur et servi dans la file d''examen ; relu comme « événement », un avis ou une autorisation devenait un faux « investissement » ou une redite.', false);
INSERT INTO public.flux_sources (flux_id, famille, sector_code, libelle, url_base, parametres, statut, qualified_by, qualified_at, note, lecture_evenementielle) VALUES ('marches_horlogerie', 'marches_financiers', 'horlogerie', 'Cours des donneurs d''ordre horlogers : variation hebdomadaire', 'https://stooq.com/q/d/l/', '{"tickers": ["uhr.sw", "cfr.sw"], "tickers_statut": "a_verifier_symboles_stooq", "fenetre_seances": 5, "seuil_variation_pct": 5.0}', 'ecarte', 'N. Castillo', '2026-08-23', 'Semé par collecte_flux.py --charger (vague A) ; qualification humaine requise avant activation | ÉCARTÉ le 23.08.2026 (décision tracée en notes de rédaction) : Stooq impose une vérification de navigateur par preuve de travail JavaScript, non contournée par principe (CGU, protocole OSINT). Blocage au niveau de la source : les symboles n''ont pu être ni confirmés ni infirmés. Repli Yahoo Finance écarté (429, CGU restrictives). Une API de cours à clé gratuite serait une piste de vague C, non instruite à ce jour.', false);
