INSERT INTO public.flux_sources (flux_id, famille, sector_code, libelle, url_base, parametres, statut, qualified_by, qualified_at, note, lecture_evenementielle) VALUES ('marches_aerospatial', 'marches_financiers', 'aerospatial', 'Cours des donneurs d''ordre aérospatiaux : variation hebdomadaire', 'https://stooq.com/q/d/l/', '{"tickers": ["air.fr", "saf.fr", "ba.us"], "tickers_statut": "a_verifier_symboles_stooq", "fenetre_seances": 5, "seuil_variation_pct": 5.0}', 'ecarte', 'N. Castillo', '2026-08-23', 'Semé par collecte_flux.py --charger (vague A) ; qualification humaine requise avant activation | ÉCARTÉ le 23.08.2026 (décision tracée en notes de rédaction) : Stooq impose une vérification de navigateur par preuve de travail JavaScript, non contournée par principe (CGU, protocole OSINT). Blocage au niveau de la source : les symboles n''ont pu être ni confirmés ni infirmés. Repli Yahoo Finance écarté (429, CGU restrictives). Une API de cours à clé gratuite serait une piste de vague C, non instruite à ce jour.', false);
INSERT INTO public.flux_sources (flux_id, famille, sector_code, libelle, url_base, parametres, statut, qualified_by, qualified_at, note, lecture_evenementielle) VALUES ('presse_aero_manufacturing', 'communications', 'aerospatial', 'Aerospace Manufacturing & Design : production aéronautique (fil RSS)', 'https://www.aerospacemanufacturinganddesign.com/rss/', '{"_note": "Presse de la PRODUCTION aéronautique : extensions d''usines, machines-outils, certifications, chaînes de fournisseurs. L''étage adressable du secteur, vu du côté industriel. Vu en réponse réelle le 26.08.2026 : 20 items."}', 'actif', 'N. Castillo (délégation du 26.08.2026)', '2026-08-26', 'Avec Medical Design & Outsourcing, l''autre source qui parle du métier et non du marché final.', true);
INSERT INTO public.flux_sources (flux_id, famille, sector_code, libelle, url_base, parametres, statut, qualified_by, qualified_at, note, lecture_evenementielle) VALUES ('gdelt_automobile', 'actualite', 'automobile', 'GDELT : actualité de la filière automobile (production, électrification)', 'https://api.gdeltproject.org/api/v2/doc/doc', '{"limite": 50, "fenetre": "7d", "requete": "(\"car production\" OR \"auto parts\" OR \"vehicle manufacturing\" OR \"EV production\")"}', 'actif', 'N. Castillo', '2026-08-24', 'GDELT DOC 2.0, requête sectorielle. Vue en réponse réelle le 22.08.2026, 50 articles.', true);
INSERT INTO public.flux_sources (flux_id, famille, sector_code, libelle, url_base, parametres, statut, qualified_by, qualified_at, note, lecture_evenementielle) VALUES ('gdelt_medical', 'actualite', 'medical', 'GDELT : actualité medtech (réglementation, investissements)', 'https://api.gdeltproject.org/api/v2/doc/doc', '{"_note": "Requête simplifiée le 23.08.2026 (décision d''étudiant, notes de rédaction). L''ancienne, à parenthèses imbriquées, était refusée en permanence par la limite de cadence de GDELT (« larger queries »), après quatre paliers d''attente 20/40/60/90 s. La simplifiée répond 200 avec 50 articles, vérifié en réponse réelle le 23.08.2026.", "limite": 50, "fenetre": "7d", "requete": "(\"medical device\" OR \"medical devices\" OR medtech)", "requete_statut": "simplifiee_23.08.2026", "requete_anterieure": "(\"medical device\" (regulation OR investment OR manufacturing OR recall))"}', 'actif', 'N. Castillo', '2026-08-24', 'GDELT DOC 2.0, requête SIMPLIFIÉE. Vue en réponse réelle le 23.08.2026, 50 articles. Réserve à porter au rapport : la requête précise, à parenthèses imbriquées, a été refusée durablement par le service (limitation de débit renvoyée en HTTP 200 avec corps non-JSON) ; la version simplifiée est un compromis dont la précision est moindre — les articles rendus ne sont pas tous pertinents.', true);
INSERT INTO public.flux_sources (flux_id, famille, sector_code, libelle, url_base, parametres, statut, qualified_by, qualified_at, note, lecture_evenementielle) VALUES ('gdelt_aerospatial', 'actualite', 'aerospatial', 'GDELT : actualité aérospatiale (commandes, cadences, lancements)', 'https://api.gdeltproject.org/api/v2/doc/doc', '{"_note": "Requête simplifiée le 23.08.2026, même motif que gdelt_medical. Répond 200 avec 49 articles, vérifié en réponse réelle le 23.08.2026. Bruit visible dans les intitulés (aviation de loisir, analyse boursière) : c''est au triage de le trancher, et le taux constaté sera une mesure.", "limite": 50, "fenetre": "7d", "requete": "(\"aircraft orders\" OR \"aerospace supplier\" OR \"aircraft production\")", "requete_statut": "simplifiee_23.08.2026", "requete_anterieure": "(aerospace (orders OR \"production rate\" OR supplier) OR \"aircraft orders\")"}', 'actif', 'N. Castillo', '2026-08-24', 'GDELT DOC 2.0, requête SIMPLIFIÉE, même réserve que gdelt_medical. Vue en réponse réelle le 23.08.2026, 49 articles, dont plusieurs manifestement hors sujet (aéroports, titres boursiers) — la charge de tri retombe sur le triage IA et l''examen humain.', true);
INSERT INTO public.flux_sources (flux_id, famille, sector_code, libelle, url_base, parametres, statut, qualified_by, qualified_at, note, lecture_evenementielle) VALUES ('boeing_communiques', 'communications', 'aerospatial', 'Boeing : communiqués de presse (fil RSS)', 'https://boeing.mediaroom.com/news-releases-statements?pagetemplate=rss', '{"_note": "Ajouté le 23.08.2026 — famille F2 du protocole OSINT, prévue en vague A par CONCEPTION_ETAGE2.md mais jamais implémentée : aucun descripteur ne la portait. Vérifié en réponse réelle le 23.08 (fil RSS valide, communiqués datés). AIRBUS ÉCARTÉ à la reconnaissance : son /rss.xml répond 200 mais ne sert que la navigation du site (« Environment », « Society »), pas les communiqués — un flux qui répond n''est pas pour autant un flux exploitable. Safran 403, Stryker 404, Medtronic sert du HTML, Swatch Group en délai d''attente, ACEA rend un fil vide."}', 'actif', 'N. Castillo', '2026-08-24', 'Fil de syndication des communiqués Boeing. Vu en réponse réelle le 23.08.2026, 5 items. Source primaire de constructeur : ce qu''elle publie est daté et attribuable, ce qui la distingue des reprises de presse.', true);
INSERT INTO public.flux_sources (flux_id, famille, sector_code, libelle, url_base, parametres, statut, qualified_by, qualified_at, note, lecture_evenementielle) VALUES ('presse_horlogerie_monochrome', 'communications', 'horlogerie', 'Monochrome Watches : presse horlogère (fil RSS)', 'https://monochrome-watches.com/feed/', '{"_note": "Presse de marché : nouveautés produits, tendances de gamme, mouvements de manufacture. Lecture pour QV2 (où va la demande) et QV4 (montre connectée, matériaux). Vu en réponse réelle le 26.08.2026 : 10 items datés."}', 'actif', 'N. Castillo (délégation du 26.08.2026)', '2026-08-26', 'Le seul fil horloger exploitable trouvé sur huit testés : Europa Star sert du HTML, WatchPro et le Journal FHH refusent (403/503), WorldTempus 404, Hodinkee un fil vide. La rareté des fils horlogers est elle-même une information sur la branche.', true);
INSERT INTO public.flux_sources (flux_id, famille, sector_code, libelle, url_base, parametres, statut, qualified_by, qualified_at, note, lecture_evenementielle) VALUES ('salon_ephj', 'communications', 'horlogerie', 'EPHJ : actualités du salon (fil RSS)', 'https://www.ephj.ch/feed/', '{"_note": "LE salon de la haute précision suisse (horlogerie-joaillerie, microtechnique, medtech) — exposants, tendances, lauréats. Un salon est un capteur d''écosystème : ce qui s''y annonce précède ce qui se produit. Couvre aussi le médical et la microtechnique. Vu en réponse réelle le 26.08.2026 : 10 items."}', 'actif', 'N. Castillo (délégation du 26.08.2026)', '2026-08-26', 'Type de source « salons » identifié à l''évaluation du 26.08 comme absent du portefeuille. EPHJ est le seul salon du périmètre avec un fil exploitable — et c''est le plus pertinent : c''est celui du tissu de sous-traitance de précision lui-même.', true);
INSERT INTO public.flux_sources (flux_id, famille, sector_code, libelle, url_base, parametres, statut, qualified_by, qualified_at, note, lecture_evenementielle) VALUES ('presse_medical_outsourcing', 'communications', 'medical', 'Medical Design & Outsourcing : sous-traitance medtech (fil RSS)', 'https://www.medicaldesignandoutsourcing.com/feed/', '{"_note": "LA presse de la sous-traitance médicale — littéralement le métier du destinataire vu du côté client : externalisation, choix de fournisseurs, usinage de précision, matériaux. Vu en réponse réelle le 26.08.2026 : 25 items."}', 'actif', 'N. Castillo (délégation du 26.08.2026)', '2026-08-26', 'La trouvaille de la reconnaissance : une source qui parle de l''étage adressable lui-même, pas du marché final.', true);
INSERT INTO public.flux_sources (flux_id, famille, sector_code, libelle, url_base, parametres, statut, qualified_by, qualified_at, note, lecture_evenementielle) VALUES ('presse_equipementiers_clepa', 'communications', 'automobile', 'CLEPA : association des équipementiers européens (fil RSS)', 'https://clepa.eu/feed/', '{"_note": "La voix officielle des équipementiers automobiles européens — l''ÉTAGE ADRESSABLE du § 8.6, qui s''exprime : positions réglementaires, alertes de filière, emploi. Source primaire d''association, pas une reprise de presse. Vu en réponse réelle le 26.08.2026 : 10 items."}', 'actif', 'N. Castillo (délégation du 26.08.2026)', '2026-08-26', 'Quand la CLEPA alerte sur la filière, c''est le carnet de commandes des sous-traitants qui parle avec six mois d''avance sur les statistiques.', true);
INSERT INTO public.flux_sources (flux_id, famille, sector_code, libelle, url_base, parametres, statut, qualified_by, qualified_at, note, lecture_evenementielle) VALUES ('presse_medtech_dive', 'communications', 'medical', 'MedTech Dive : presse medtech (fil RSS)', 'https://www.medtechdive.com/feeds/news/', '{"_note": "Presse professionnelle medtech : autorisations, rappels, stratégie des fabricants, chaînes d''approvisionnement. Complète M8 (510k) par le contexte que le décompte ne porte pas. Vu en réponse réelle le 26.08.2026 : 10 items."}', 'actif', 'N. Castillo (délégation du 26.08.2026)', '2026-08-26', 'Presse spécialisée de premier rang, gratuite, quotidienne.', true);
INSERT INTO public.flux_sources (flux_id, famille, sector_code, libelle, url_base, parametres, statut, qualified_by, qualified_at, note, lecture_evenementielle) VALUES ('presse_auto_electrive', 'communications', 'automobile', 'electrive : transition électrique de l''automobile (fil RSS)', 'https://www.electrive.com/feed/', '{"_note": "Presse spécialisée de la transition électrique : investissements d''usines, annonces de capacité, choix technologiques. C''est QV4 (dynamique technologique) en flux — la recomposition des familles de pièces qui touche directement un usineur. Vu en réponse réelle le 26.08.2026 : 30 items."}', 'actif', 'N. Castillo (délégation du 26.08.2026)', '2026-08-26', 'Just Auto, vivant, a été écarté : généraliste, il recouvre CLEPA et electrive sans leur angle.', true);
INSERT INTO public.flux_sources (flux_id, famille, sector_code, libelle, url_base, parametres, statut, qualified_by, qualified_at, note, lecture_evenementielle) VALUES ('ted_automobile_v2', 'marches_publics', 'automobile', 'Avis TED : moteurs et pièces mécaniques automobiles (CPV 34310/34312/34320)', 'https://api.ted.europa.eu/v3/notices/search', '{"cpv": "34310000, 34312000, 34320000", "_note": "CPV affiné le 23.08.2026 (décision d''étudiant). Analyse de 250 avis sur 30 jours : sous 34300000, les pneumatiques (34350/34351/34352) pèsent 82 avis et l''entretien de flottes 38 — ni l''un ni l''autre ne relève de l''usinage de précision. Le jeu retenu cible les pièces mécaniques usinées : 34310000 moteurs et pièces de moteurs, 34312000 pièces de moteurs, 34320000 pièces de rechange mécaniques hors moteurs. Volume divisé par six (11 avis sur 7 jours contre 70) et intitulés vérifiés en réponse réelle : « Moteurs et pièces de moteurs (véhicules) », « Pièces de moteurs », « Pièces de rechange mécaniques, excepté moteurs et parties de moteurs ». LEVIER LAISSÉ OUVERT : ajouter 34330000 (pièces de rechange pour véhicules) porterait le volume à 20 avis sur 7 jours, au prix d''un élargissement générique — non retenu, à rouvrir si le flux se révèle trop maigre. | 23.08.2026 : fenêtre portée de 7 à 30 jours (décision de l''étudiant). L''API TED est libre et le volume mensuel reste modeste ; la fenêtre courte privait la file d''examen de matière. Limite portée à 100 : le volume mensuel de ce CPV tient sous ce plafond, la fenêtre n''est donc pas tronquée par la limite.", "limite": 100, "cpv_statut": "affine_23.08.2026_verifie_en_intitules", "fenetre_jours": 30}', 'actif', 'N. Castillo', '2026-08-24', 'CPV affinés 34310000, 34312000, 34320000 (moteurs, pièces de moteurs, pièces mécaniques). Vérifiés en réponse réelle le 23.08.2026 : 163 avis sur 60 jours, tous enrichis. Remplace ted_automobile, dont le CPV 34300000 était trop large. | NON ÉLIGIBLE à la lecture événementielle (01.09.2026) : enregistrement structuré, compté par indicateur et servi dans la file d''examen ; relu comme « événement », un avis ou une autorisation devenait un faux « investissement » ou une redite.', false);
INSERT INTO public.flux_sources (flux_id, famille, sector_code, libelle, url_base, parametres, statut, qualified_by, qualified_at, note, lecture_evenementielle) VALUES ('ted_automobile', 'marches_publics', 'automobile', 'Avis TED : véhicules et pièces (division 34.3)', 'https://api.ted.europa.eu/v3/notices/search', '{"cpv": "34300000", "_note": "CONSERVÉ EN PREUVE (décision du 23.08.2026). Le CPV 34300000 capte l''ensemble de la branche « parties et accessoires », y compris les pneumatiques et — surtout — les marchés d''entretien de flottes où il n''est qu''un code secondaire derrière 50110000/50100000. Triage du 22.08 : 49 items sur 50 notés 0, taux de rétention 2 %. Ce flux n''est pas corrigé : il documente la vigilance F3 du protocole OSINT (« bruit élevé, tri indispensable ») confirmée sur pièces. Remplacé en exploitation par ted_automobile_v2. | 23.08.2026 : fenêtre portée de 7 à 30 jours (décision de l''étudiant). L''API TED est libre et le volume mensuel reste modeste ; la fenêtre courte privait la file d''examen de matière. Limite maintenue à 50 : le volume mensuel de ce CPV se compte en centaines (automobile large) ou en milliers (médical), et la file d''examen humaine ne s''inonde pas — la limite mord donc avant la fenêtre, ce qui est assumé.", "limite": 50, "cpv_statut": "a_verifier", "fenetre_jours": 30}', 'ecarte', 'N. Castillo', '2026-08-24', 'CPV 34300000 (pièces et accessoires pour véhicules), trop large : la lecture décisionnelle y a trouvé un avis adressable sur 39. Remplacé par ted_automobile_v2 aux CPV affinés le 23.08.2026. Écarté de la collecte, CONSERVÉ EN PREUVE : les 250 avis déjà en base établissent la comparaison avant/après affinage. | NON ÉLIGIBLE à la lecture événementielle (01.09.2026) : enregistrement structuré, compté par indicateur et servi dans la file d''examen ; relu comme « événement », un avis ou une autorisation devenait un faux « investissement » ou une redite.', false);
INSERT INTO public.flux_sources (flux_id, famille, sector_code, libelle, url_base, parametres, statut, qualified_by, qualified_at, note, lecture_evenementielle) VALUES ('fda_510k_medical', 'reglementaire', 'medical', 'openFDA : autorisations 510(k) de dispositifs médicaux', 'https://api.fda.gov/device/510k.json', '{"_note": "Ajouté le 23.08.2026, chantier des signaux faibles. AMONT AU SENS STRICT : une autorisation de mise sur le marché précède la montée en cadence de production, donc la charge d''usinage, donc toute statistique qui la constatera. Vérifié en réponse réelle le 23.08 : 161 autorisations sur 30 jours, API libre et sans clé. Fenêtre portée de 7 à 30 jours le 23.08 : sur 7 jours la recherche est vide, les décisions étant publiées avec retard.", "limite": 50, "prefixe": "FDA 510(k)", "champ_id": "k_number", "champ_date": "decision_date", "url_detail": "https://www.accessdata.fda.gov/scripts/cdrh/cfdocs/cfpmn/pmn.cfm?ID={ident}", "champ_acteur": "applicant", "champ_libelle": "device_name", "fenetre_jours": 30}', 'actif', 'N. Castillo', '2026-08-24', 'openFDA, point d''accès 510(k), sans clé d''API. Vu en réponse réelle le 23.08.2026, 50 items. Deux particularités de transport documentées et traitées : le séparateur +TO+ des bornes de date ne doit pas être encodé, et un code 404 signifie « aucun résultat », non une erreur. Alimente M8 (comptage mensuel) et la file d''examen. | NON ÉLIGIBLE à la lecture événementielle (01.09.2026) : enregistrement structuré, compté par indicateur et servi dans la file d''examen ; relu comme « événement », un avis ou une autorisation devenait un faux « investissement » ou une redite.', false);
INSERT INTO public.flux_sources (flux_id, famille, sector_code, libelle, url_base, parametres, statut, qualified_by, qualified_at, note, lecture_evenementielle) VALUES ('fda_rappels_medical', 'reglementaire', 'medical', 'openFDA : rappels de dispositifs médicaux', 'https://api.fda.gov/device/recall.json', '{"_note": "Ajouté le 23.08.2026. Un rappel signale une défaillance de conception ou de fabrication : c''est un signal de contrainte technique en amont des exigences qui se répercuteront sur les sous-traitants. Volume faible (3 sur 30 jours au 23.08) : fenêtre portée à 30 jours à dessein.", "limite": 50, "prefixe": "FDA rappel", "champ_id": "product_res_number", "champ_date": "event_date_initiated", "url_detail": "", "champ_acteur": "recalling_firm", "champ_libelle": "product_description", "fenetre_jours": 30}', 'actif', 'N. Castillo', '2026-08-24', 'openFDA, point d''accès des rappels de dispositifs. Vu en réponse réelle le 23.08.2026, 3 items sur la fenêtre. Volume faible assumé : un rappel est un événement rare, et c''est précisément sa rareté qui en fait un signal. | NON ÉLIGIBLE à la lecture événementielle (01.09.2026) : enregistrement structuré, compté par indicateur et servi dans la file d''examen ; relu comme « événement », un avis ou une autorisation devenait un faux « investissement » ou une redite.', false);
INSERT INTO public.flux_sources (flux_id, famille, sector_code, libelle, url_base, parametres, statut, qualified_by, qualified_at, note, lecture_evenementielle) VALUES ('ted_ferroviaire', 'marches_publics', NULL, 'Avis TED : pièces de locomotives et matériel ferroviaire roulant (CPV 34630000)', 'https://api.ted.europa.eu/v3/notices/search', '{"cpv": "34630000", "_note": "Ajouté le 24.08.2026 sur une DÉCOUVERTE DU DISPOSITIF, non sur une hypothèse : la lecture décisionnelle des 77 appels ouverts n''a retenu que trois avis adressables, et les TROIS étaient des pièces de freins FERROVIAIRES (Roumanie, Hongrie, Italie). Le ferroviaire n''appartient à aucun des quatre marchés surveillés. SECTEUR VOLONTAIREMENT NUL : ajouter un cinquième secteur à la grille est une décision de l''étudiant, pas une conséquence technique. Le flux alimente l''écran Actions sans toucher au cadre du ch. 8. CPV vérifié en intitulés le 24.08 : « Pièces détachées pour locomotives ou matériel ferroviaire roulant », 381 avis sur 60 jours.", "limite": 100, "cpv_statut": "verifie_24.08.2026_en_intitules", "fenetre_jours": 30}', 'actif', 'N. Castillo', '2026-08-24', 'CPV 34630000 (pièces de locomotives et matériel ferroviaire roulant). Vérifié en intitulés sur réponse réelle le 24.08.2026 : 381 avis sur 60 jours, intitulés confirmés comme pièces et non voie ni matériel complet. Ajouté sur découverte du dispositif, non sur hypothèse — les seuls avis usinables des trois autres secteurs étaient ferroviaires. SECTEUR NUL À DESSEIN : l''extension de la grille du ch. 8 à un cinquième marché reste à trancher en supervision. | NON ÉLIGIBLE à la lecture événementielle (01.09.2026) : enregistrement structuré, compté par indicateur et servi dans la file d''examen ; relu comme « événement », un avis ou une autorisation devenait un faux « investissement » ou une redite.', false);
INSERT INTO public.flux_filtrage_regles (regle_code, libelle, enonce, seuil, active, cree_le, fondement) VALUES ('seuil_v1', 'Seuil de triage à 3, avec garde-fou d''antériorité', 'Un item est écarté sans examen humain si sa note de triage sous la doctrine « signal » (antériorité + portée + pertinence, sur 6) est strictement inférieure à 3, SAUF si son antériorité vaut 2 — un item jugé fortement anticipateur est toujours soumis à l''humain, quelle que soit sa note globale. Les items non triés ne sont jamais filtrés.', 3, true, '2026-08-26 20:09:56.566385+00', 'Sur 37 items examinés au 26.08.2026, aucun item noté 2 ou moins n''a produit de signal (14 examinés : 13 écartés, 1 retenu en contexte). Le seul signal promu venait d''un item noté 6. Les deux doctrines de triage convergent : aucun item faible en « signal » n''est fort en « evenement ». LIMITE ASSUMÉE : quatorze observations ne fondent pas une loi. La règle est provisoire et sa validation permanente est l''échantillon d''audit mensuel.');
